import { create } from "zustand";

export const useGameStore = create((set, get) => ({
  slices: {},
}));

export const GameStore = {
  getState: (sliceKey) => {
    const s = useGameStore.getState().slices;
    return sliceKey ? s[sliceKey] : s;
  },

  setState: (sliceKey, updater) => {
    useGameStore.setState((prev) => {
      const prevSlice = prev.slices[sliceKey];
      const nextSlice =
        typeof updater === "function"
          ? updater(prevSlice)
          : { ...prevSlice, ...updater };
      return { slices: { ...prev.slices, [sliceKey]: nextSlice } };
    });
  },

  subscribe: (sliceKey, fn) => {
    return useGameStore.subscribe((state, prevState) => {
      if (state.slices[sliceKey] !== prevState.slices[sliceKey]) {
        fn(state.slices[sliceKey], prevState.slices[sliceKey]);
      }
    });
  },

  registerSlice: (sliceKey, initialState) => {
    useGameStore.setState((prev) => ({
      slices: { ...prev.slices, [sliceKey]: initialState },
    }));
  },

  optimistic: async (
    sliceKey,
    optimisticUpdate,
    asyncAction,
    onSuccess,
    onError,
  ) => {
    const snapshot = { ...GameStore.getState(sliceKey) };
    GameStore.setState(sliceKey, optimisticUpdate);
    try {
      const result = await asyncAction();
      if (result && result.error) {
        GameStore.setState(sliceKey, () => snapshot);
        if (onError) onError(result.error, snapshot);
        return result;
      }
      if (onSuccess) {
        GameStore.setState(sliceKey, (current) => onSuccess(result, current));
      }
      return result;
    } catch (err) {
      GameStore.setState(sliceKey, () => snapshot);
      if (onError) onError(err, snapshot);
      throw err;
    }
  },
};

/* тХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХР
 *  Game Hub тАФ Auth UI (Simple Login/Register)
 *  Creates a <dialog> overlay for non-Discord access
 * тХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХР */

const AUTH_TOKEN_KEY = "hub_auth_token";
const AUTH_USER_KEY = "hub_auth_user";

/** Check if user has a stored session */
export function getStoredAuth() {
  try {
    const token = localStorage.getItem(AUTH_TOKEN_KEY);
    const user = localStorage.getItem(AUTH_USER_KEY);
    if (token && user) {
      return { token, ...JSON.parse(user) };
    }
  } catch { /* ignore corrupt storage */ }
  return null;
}

/** Store session after login/register */
export function storeAuth(token, userId, username) {
  localStorage.setItem(AUTH_TOKEN_KEY, token);
  localStorage.setItem(AUTH_USER_KEY, JSON.stringify({ userId, username }));
}

/** Clear stored session */
export function clearAuth() {
  localStorage.removeItem(AUTH_TOKEN_KEY);
  localStorage.removeItem(AUTH_USER_KEY);
}

/** Validate stored token against server */
export async function validateStoredToken() {
  const stored = getStoredAuth();
  if (!stored) return null;

  try {
    const res = await fetch("/api/auth/me", {
      headers: { Authorization: `Bearer ${stored.token}` },
    });
    if (!res.ok) {
      clearAuth();
      return null;
    }
    const data = await res.json();
    return { token: stored.token, userId: data.userId, username: data.username };
  } catch {
    return null; // Network error тАФ keep stored auth, don't clear
  }
}

