/* тХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХР
 *  Game Hub тАФ Crops Data Module (v6.2.0)
 *  Centralizes crop metadata fetching and caching.
 *  Replaces window.__cropsPromise / window.__cropsCache globals.
 * тХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХР */

let _cache = null;
let _promise = null;

const STORAGE_KEY = "hub_crops_cache";
const TTL = 24 * 60 * 60 * 1000; // 24h

/** Start fetching crops data (call early, in parallel with auth) */
export function prefetchCrops() {
  _promise = fetch("/api/content/crops")
    .then((r) => (r.ok ? r.json() : null))
    .then((data) => {
      if (data) _cache = data;
      return data;
    })
    .catch(() => {
      // Fallback: try localStorage cache with TTL
      return _loadFromStorage();
    });
}

/** Get crops data (sync if already cached, async otherwise) */
export async function getCropsData() {
  if (_cache) return _cache;
  if (_promise) return _promise;
  // Neither cached nor prefetched тАФ fetch now
  prefetchCrops();
  return _promise;
}

/** Get cached crops data synchronously (may be null) */
export function getCropsCache() {
  return _cache;
}

/** Update the crops cache (called by farm.js after fetch) */
export function setCropsCache(data) {
  _cache = data;
}

/** Load from localStorage with TTL check */
function _loadFromStorage() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (parsed && parsed.cachedAt) {
      if (Date.now() - parsed.cachedAt > TTL) return null;
      _cache = parsed.data;
      return parsed.data;
    }
    // Legacy format
    _cache = parsed;
    return parsed;
  } catch (_) {
    return null;
  }
}

/** Pre-populate cache from localStorage (sync, for preventing fallback emojis) */
export function loadCropsFromStorage() {
  return _loadFromStorage();
}

/* тХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХР
 *  Game Hub тАФ Shared Effects Module (v6.2.1)
 *  Centralised visual + audio effects.
 *  Previously: perlinShake was duplicated in match3.js and blox.js.
 *  Now: single source of truth for all spFX.
 *
 *  Exports:
 *    perlinShake(el, intensity, durationMs)
 *    colorSplash(el, color, durationMs?)
 *    debounce(fn, wait)
 *    SoundEngine  тАФ Web Audio API synthesis + Vibration API
 * тХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХР */

/* тФАтФАтФА Perlin Noise Screen Shake тФАтФАтФА */
function _hashNoise(x) {
  const n = Math.sin(x * 127.1 + x * 311.7) * 43758.5453;
  return (n - Math.floor(n)) * 2 - 1; // -1..+1
}
function _smoothNoise(t) {
  const i = Math.floor(t);
  const f = t - i;
  const u = f * f * (3 - 2 * f);
  return _hashNoise(i) * (1 - u) + _hashNoise(i + 1) * u;
}

/**
 * Organic Perlin-noise screen shake with linear decay.
 * Compositor-only: only writes transform, never triggers layout.
 * @param {HTMLElement} el       тАФ element to shake
 * @param {number} intensity     тАФ max pixel displacement
 * @param {number} durationMs    тАФ total shake duration in ms
 */
export function perlinShake(el, intensity, durationMs) {
  if (!el || document.hidden) return; // skip if tab is backgrounded
  const start = performance.now();
  const seed = Math.random() * 1000;
  function frame(now) {
    const elapsed = now - start;
    if (elapsed >= durationMs) {
      el.style.transform = "";
      return;
    }
    const decay = 1 - elapsed / durationMs;
    const t = elapsed * 0.015;
    const x = _smoothNoise(seed + t) * intensity * decay;
    const y = _smoothNoise(seed + t + 100) * intensity * decay;
    const r = _smoothNoise(seed + t + 200) * intensity * 0.15 * decay;
    el.style.transform = `translate(${x.toFixed(1)}px, ${y.toFixed(1)}px) rotate(${r.toFixed(2)}deg)`;
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
}

/**
 * Brief color splash тАФ board background flares with gem/harvest color.
 * Uses box-shadow inset so it never touches layout.
 * @param {HTMLElement} el      тАФ element to flash
 * @param {string} color        тАФ CSS color string (hex / hsl / rgb)
 * @param {number} durationMs   тАФ fade-out duration (default 600ms)
 */
export function colorSplash(el, color, durationMs = 600) {
  if (!el) return;
  el.style.transition = "box-shadow 0s";
  el.style.boxShadow = `inset 0 0 60px 20px ${color}55`;
  requestAnimationFrame(() => {
    el.style.transition = `box-shadow ${durationMs}ms ease-out`;
    el.style.boxShadow = "";
  });
}

/**
 * Simple debounce тАФ delays fn until `wait` ms after last call.
 * Returned function has a `.cancel()` method for cleanup on onLeave.
 * @param {Function} fn
 * @param {number} wait тАФ debounce period in ms
 */
export function debounce(fn, wait) {
  let timer = null;
  function debounced(...args) {
    if (timer) clearTimeout(timer);
    timer = setTimeout(() => {
      timer = null;
      fn(...args);
    }, wait);
  }
  debounced.cancel = () => {
    if (timer) {
      clearTimeout(timer);
      timer = null;
    }
  };
  debounced.flush = (...args) => {
    if (timer) {
      clearTimeout(timer);
      timer = null;
      fn(...args);
    }
  };
  return debounced;
}

/* тФАтФАтФА SoundEngine тАФ Web Audio API synthesis + Vibration API тФАтФАтФА */
/**
 * Zero-asset audio engine: all sounds synthesised via Web Audio API.
 * No files, no network requests, no permissions needed.
 * Vibration API (navigator.vibrate) adds haptic feedback on Android.
 *
 * Volume persists in localStorage as 'hub_sfx_vol' (0тАУ1, default 0.4).
 * Muted when volume === 0.
 */
export const SoundEngine = (() => {
  let _ctx = null;
  let _vol = parseFloat(localStorage.getItem("hub_sfx_vol") ?? "0.4");

  function _getCtx() {
    if (!_ctx) {
      _ctx = new (window.AudioContext || window.webkitAudioContext)();
    }
    // Browsers suspend AudioContext until user gesture
    if (_ctx.state === "suspended") _ctx.resume();
    return _ctx;
  }

  /**
   * @param {object} opts
   * @param {number}  opts.freq      тАФ oscillator frequency (Hz)
   * @param {string}  [opts.type]    тАФ OscillatorType: 'sine'|'square'|'triangle'|'sawtooth'
   * @param {number}  [opts.duration] тАФ note duration (seconds)
   * @param {number}  [opts.gain]    тАФ 0тАУ1 per-note volume multiplier
   */
  function _playTone({
    freq = 440,
    type = "sine",
    duration = 0.1,
    gain = 0.5,
  }) {
    if (_vol <= 0) return;
    try {
      const c = _getCtx();
      const osc = c.createOscillator();
      const vol = c.createGain();
      osc.type = type;
      osc.frequency.setValueAtTime(freq, c.currentTime);
      vol.gain.setValueAtTime(gain * _vol, c.currentTime);
      vol.gain.exponentialRampToValueAtTime(0.001, c.currentTime + duration);
      osc.connect(vol);
      vol.connect(c.destination);
      osc.start();
      osc.stop(c.currentTime + duration);
    } catch (_) {
      /* AudioContext not available тАФ ignore */
    }
  }

  function _vib(pattern) {
    navigator.vibrate?.(pattern);
  }

  return {
    /** Get / set volume (0тАУ1). Persists to localStorage. */
    getVolume: () => _vol,
    setVolume: (v) => {
      _vol = Math.max(0, Math.min(1, v));
      localStorage.setItem("hub_sfx_vol", String(_vol));
    },

    /* тФАтФА Game events тФАтФА */
    /** Gem matches or single line clear */
    match() {
      _playTone({ freq: 660, type: "sine", duration: 0.08, gain: 0.35 });
      _vib(12);
    },
    /** Combo cascade тАФ n increases pitch */
    combo(n = 1) {
      _playTone({
        freq: 440 + n * 80,
        type: "square",
        duration: 0.12,
        gain: 0.18,
      });
      _vib([18, 8, 18]);
    },
    /** Successful harvest */
    harvest() {
      _playTone({ freq: 880, type: "triangle", duration: 0.15, gain: 0.3 });
      _vib(22);
    },
    /** Successful merge (Gacha Merge board) */
    merge() {
      _playTone({ freq: 523, type: "sine", duration: 0.2, gain: 0.4 });
      _vib([10, 5, 30]);
    },
    /** Gacha / free pull */
    gacha() {
      _playTone({ freq: 784, type: "triangle", duration: 0.25, gain: 0.35 });
      _vib([15, 10, 25, 5, 40]);
    },
    /** Plant seed */
    plant() {
      _playTone({ freq: 440, type: "triangle", duration: 0.1, gain: 0.2 });
    },
    /** Invalid move / error */
    error() {
      _playTone({ freq: 200, type: "sawtooth", duration: 0.15, gain: 0.15 });
      _vib(45);
    },
    /** Multi-line clear (Blox) */
    multiLine() {
      _playTone({ freq: 740, type: "square", duration: 0.18, gain: 0.22 });
      _vib([20, 10, 40]);
    },
    /** Game over */
    gameOver() {
      _playTone({ freq: 180, type: "sawtooth", duration: 0.5, gain: 0.2 });
      _vib([80, 40, 80]);
    },
    /** Quest complete */
    questComplete() {
      _playTone({ freq: 660, type: "triangle", duration: 0.3, gain: 0.3 });
      _vib([20, 10, 20, 10, 40]);
    },
    /** Button click (light) */
    click() {
      _playTone({ freq: 1000, type: "sine", duration: 0.04, gain: 0.1 });
    },
  };
})();

/* тХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХР
