  /* тФАтФАтФА Horizontal Buy Bar тФАтФАтФА */
  function updateBuyBar() {
    const bar = $("farm-buy-bar");
    if (!bar) return;

    if (!selectedSeed || !crops[selectedSeed]) {
      bar.style.display = "none";
      return;
    }

    bar.style.display = "";
