      <button class="buy-bar-btn${canAfford ? "" : " disabled"}" id="buy-bar-go">${canAfford ? "Buy" : "ЁЯТ░?"}</button>
    `;

    function setQty(q) {
      buyQty = Math.max(1, Math.min(99, q));
