      updateBuyBar();
    }
    $("buy-qty-m10").onclick = () => setQty(buyQty - 10);
    $("buy-qty-minus").onclick = () => setQty(buyQty - 1);
    $("buy-qty-plus").onclick = () => setQty(buyQty + 1);
    $("buy-qty-p10").onclick = () => setQty(buyQty + 10);
    $("buy-bar-go").onclick = () => {
      if (canAfford) buySeeds(selectedSeed);
    };
