  /* тФАтФАтФА Actions тФАтФАтФА */
  let buySeedVersion = 0;
  function buySeeds(cropId) {
    const cfg = crops[cropId];
    if (!cfg) return;
    const totalCost = cfg.seedPrice * buyQty;
    const goldAvail = HUD.getGold();
    if (goldAvail < totalCost) {
      showToast("тЭМ Not enough gold!");
      return;
    }
    // Bug 1 fix: immediately deduct gold from GameStore for instant UI
    const prevGold = goldAvail;
    const res = GameStore.getState("resources") || {};
    GameStore.setState("resources", { ...res, gold: res.gold - totalCost });
    // Optimistic update (instant UI)
    const prevInventory = { ...state.inventory };
    const savedQty = buyQty;
    state.inventory[cropId] = (state.inventory[cropId] || 0) + savedQty;
    syncToStore();
    render();
    renderShop();
    showToast(`Bought ${savedQty}├Ч ${cfg.emoji} ${cfg.name} seeds`);
    HUD.animateGoldChange(-totalCost);
    buyQty = 1;
    if (selectedSeed) saveBuyQty(selectedSeed, 1);
    updateBuyBar();

    // Fire-and-forget with version guard
    const myVersion = ++buySeedVersion;
    apiBatched("/api/farm/buy-seeds", {
      userId: HUB.userId,
      cropId,
      amount: savedQty,
    })
      .then((data) => {
        if (buySeedVersion !== myVersion || data._optimistic) return;
        if (data.success) {
          // Silently sync server state
          if (data.resources) {
            HUD.syncFromServer(data.resources);
          }
          if (data.inventory) state.inventory = data.inventory;
          syncToStore();
        } else {
          // Rollback gold + inventory
          const res = GameStore.getState("resources") || {};
          GameStore.setState("resources", { ...res, gold: prevGold });
          state.inventory = prevInventory;
          syncToStore();
          render();
          renderShop();
          showToast(`тЭМ ${data.error}`);
        }
      })
      .catch(() => {
        if (buySeedVersion === myVersion) loadState();
      });
  }

  /* тХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХР
   *  v7.1: Contextual Quick-Buy тАФ Bottom Sheet
   *  Shows top 3 seeds when tapping an empty plot.
   *  Single tap = buy 1 seed + plant instantly.
   * тХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХР */
  const PURCHASE_HISTORY_KEY = "farm_purchase_history";
  const PURCHASE_HISTORY_MAX = 50;

  function _getPurchaseHistory() {
    try {
      return JSON.parse(localStorage.getItem(PURCHASE_HISTORY_KEY) || "[]");
    } catch {
      return [];
    }
  }

  function _trackPurchase(seedId) {
    const history = _getPurchaseHistory();
    history.push({ seedId, ts: Date.now() });
    // FIFO cap
    while (history.length > PURCHASE_HISTORY_MAX) history.shift();
    localStorage.setItem(PURCHASE_HISTORY_KEY, JSON.stringify(history));
  }

  /** Get top N most-purchased seed IDs. Fallback: cheapest N. */
  function _getTopSeeds(n = 3) {
    const history = _getPurchaseHistory();
    // v7.2: Only consider unlocked seeds
    const unlocked = _computeUnlocked();
    // Count purchases per seed
    const counts = {};
    for (const { seedId } of history) {
      counts[seedId] = (counts[seedId] || 0) + 1;
    }
    // Sort by purchase count descending, filter to unlocked only
    const ranked = Object.entries(counts)
      .filter(
        ([id]) => crops[id] && !id.startsWith("__") && unlocked.includes(id),
      )
      .sort(([, a], [, b]) => b - a)
      .map(([id]) => id);

    if (ranked.length >= n) return ranked.slice(0, n);

    // Fallback: fill with cheapest unlocked seeds not already in the list
    const allSeeds = Object.entries(crops)
      .filter(
        ([id, cfg]) =>
          typeof cfg === "object" &&
          cfg !== null &&
          !id.startsWith("__") &&
          unlocked.includes(id),
      )
      .sort(([, a], [, b]) => (a.seedPrice || 0) - (b.seedPrice || 0))
      .map(([id]) => id);
    const merged = [...ranked];
    for (const id of allSeeds) {
      if (merged.length >= n) break;
      if (!merged.includes(id)) merged.push(id);
    }
    return merged.slice(0, n);
  }

  function showQuickBuy(plotId) {
    // Don't show if no crops loaded
    if (!crops || Object.keys(crops).length === 0) {
      showToast("ЁЯЫТ Loading seeds...");
      return;
    }
    // Prevent duplicate sheets
    const existing = document.getElementById("quick-buy-dialog");
    if (existing) existing.remove();

    const topSeeds = _getTopSeeds(3);
    const goldAvail = HUD.getGold();

    // Find most-purchased seed for "тШЕ" indicator
    const history = _getPurchaseHistory();
    const counts = {};
    for (const { seedId } of history)
      counts[seedId] = (counts[seedId] || 0) + 1;
    const favSeed = Object.entries(counts).sort(
      ([, a], [, b]) => b - a,
    )[0]?.[0];

    // Build seed cards
    const cards = topSeeds
      .map((id) => {
        const cfg = crops[id];
        if (!cfg) return "";
        const canonicalGrowth =
          CROPS_CONFIG[id]?.growthTime || cfg.growthTime || 15000;
        const growthLabel = _formatGrowthTime(canonicalGrowth);
        const canAfford = goldAvail >= (cfg.seedPrice || 0);
        const isFav = id === favSeed;
        const invCount = state?.inventory?.[id] || 0;

        return `
        <button class="qb-seed-card${canAfford ? "" : " qb-muted"}" data-seed="${id}" ${canAfford ? "" : "disabled"}>
          <span class="qb-seed-emoji">${cfg.emoji}</span>
          <span class="qb-seed-info">
            <span class="qb-seed-name">${isFav ? "тШЕ " : ""}${cfg.name}</span>
            <span class="qb-seed-meta">тП▒ ${growthLabel}${invCount > 0 ? ` ┬╖ ЁЯОТ${invCount}` : ""}</span>
          </span>
          <span class="qb-seed-price${canAfford ? "" : " qb-price-red"}">ЁЯкЩ ${cfg.seedPrice || 0}</span>
        </button>
      `;
      })
      .join("");

    const dialog = document.createElement("dialog");
    dialog.id = "quick-buy-dialog";
    dialog.className = "modal quick-buy-sheet";
    dialog.innerHTML = `
      <div class="qb-card">
        <div class="qb-header">
          <span class="qb-title">ЁЯМ▒ Quick Plant</span>
          <span class="qb-balance">ЁЯкЩ ${goldAvail}</span>
        </div>
        ${cards}
        <button class="qb-more-link" id="qb-more">тЛп More in Seed Shop</button>
      </div>
    `;

    // Event handlers
    dialog.addEventListener("close", () => dialog.remove());
    dialog.addEventListener("click", (e) => {
      if (e.target === dialog) dialog.close();
    });

    // Seed card tap тЖТ buy 1 + plant instantly
    dialog.querySelectorAll(".qb-seed-card:not([disabled])").forEach((btn) => {
      btn.addEventListener("click", () => {
        const seedId = btn.dataset.seed;
        dialog.close();
        _quickBuyAndPlant(seedId, plotId);
      });
    });

    // Muted card tap тЖТ shake + tooltip
    dialog.querySelectorAll(".qb-seed-card[disabled]").forEach((btn) => {
      btn.addEventListener("click", (e) => {
        e.preventDefault();
        const seedId = btn.dataset.seed;
        const cfg = crops[seedId];
        const deficit = (cfg?.seedPrice || 0) - goldAvail;
        btn.classList.add("qb-shake");
        showToast(`Need ${deficit}ЁЯкЩ more`);
        setTimeout(() => btn.classList.remove("qb-shake"), 400);
      });
    });

    // "More in Seed Shop" link
    dialog.querySelector("#qb-more")?.addEventListener("click", () => {
      dialog.close();
      if (FarmGameImpl.switchFarmTab) FarmGameImpl.switchFarmTab("shop");
      else {
        const shopEl = document.querySelector(".farm-shop");
        if (shopEl) shopEl.scrollIntoView({ behavior: "smooth" });
      }
    });

    document.body.appendChild(dialog);
    import("./shared.js").then(({ safeShowModal }) => safeShowModal(dialog));
  }

  /** Buy 1 seed + plant it in the given plot (single-tap flow) */
  function _quickBuyAndPlant(seedId, plotId) {
    const cfg = crops[seedId];
    if (!cfg) return;
    const goldAvail = HUD.getGold();
    const price = cfg.seedPrice || 0;
    if (goldAvail < price) {
      showToast("тЭМ Not enough gold!");
      return;
    }

    // Track purchase for history-based recommendations
    _trackPurchase(seedId);

    // Optimistic: deduct gold + add to inventory
    const res = GameStore.getState("resources") || {};
    GameStore.setState("resources", { ...res, gold: res.gold - price });
    state.inventory[seedId] = (state.inventory[seedId] || 0) + 1;
    syncToStore();
    HUD.animateGoldChange(-price);

    // Now plant using the seed
    selectedSeed = seedId;
    plant(plotId);
    // plant() will deduct 1 from inventory and call the plant API

    // Buy API call (fire-and-forget, same pattern as buySeeds)
    const prevGold = goldAvail;
    const myVersion = ++buySeedVersion;
    apiBatched("/api/farm/buy-seeds", {
      userId: HUB.userId,
      cropId: seedId,
      amount: 1,
    })
      .then((data) => {
        if (buySeedVersion !== myVersion || data._optimistic) return;
        if (data.success) {
          if (data.resources) HUD.syncFromServer(data.resources);
          if (data.inventory) state.inventory = data.inventory;
          syncToStore();
        } else {
          // Rollback gold only тАФ do NOT re-render farm grid
          // (plant API handles inventory; re-rendering here would
          //  overwrite the already-planted optimistic plot state)
          const res = GameStore.getState("resources") || {};
          GameStore.setState("resources", { ...res, gold: prevGold });
          syncToStore();
          showToast(`тЭМ ${data.error}`);
        }
      })
      .catch(() => {
        if (buySeedVersion === myVersion) loadState();
      });

    // Show feedback
    showToast(`Planted ${cfg.emoji} ${cfg.name}!`);
  }

  function plant(plotId) {
    if (!selectedSeed) {
      // v7.1: Contextual Quick-Buy тАФ show bottom sheet instead of scrolling to shop
      showQuickBuy(plotId);
      return;
    }
    const seedCount = state?.inventory?.[selectedSeed] || 0;
    if (seedCount <= 0) {
      showToast("ЁЯМ╛ No seeds left! Buy more in the shop тЖУ");
      const shopEl = document.querySelector(".farm-shop");
      if (shopEl) shopEl.scrollIntoView({ behavior: "smooth" });
      return;
    }
    // Optimistic update (instant UI feedback)
    const cropId = selectedSeed;
    state.plots[plotId] = {
      ...state.plots[plotId],
      crop: cropId,
      plantedAt: getServerNow(), // v4.9: use server-corrected time for optimistic plant
      watered: false,
      growthTime: crops[cropId]?.growthTime || 15000,
    };
    state.inventory[cropId] = Math.max(0, seedCount - 1);
    justPlantedPlot = plotId;
    syncToStore();
    render();
    renderShop();
    updateBuyBar();

    // Phase 2 Item 5: Dirt Splash particle on plant
    const plotDiv = document.querySelector(
      `.farm-plot[data-index="${plotId}"]`,
    );
    if (plotDiv) {
      const cropEmoji = plotDiv.querySelector(".crop-emoji");
      if (cropEmoji) cropEmoji.classList.add("planted-bounce");
      spawnDirtSplash(plotDiv);
    }

    // Fire-and-forget with PER-PLOT version guard (Bug 4 fix)
    const ver = (plotPlantVersions.get(plotId) || 0) + 1;
    plotPlantVersions.set(plotId, ver);
    apiBatched("/api/farm/plant", {
      userId: HUB.userId,
      plotId,
      cropId,
    })
      .then((data) => {
        // Only process if this plot hasn't been re-planted since
        if (plotPlantVersions.get(plotId) !== ver || data._optimistic) return;
        if (data.success) {
          // Silently sync server state тАФ NO re-render (optimistic UI is correct)
          if (data.plots) state.plots = data.plots;
          if (data.inventory) state.inventory = data.inventory;
          syncToStore();
        } else {
          // Error: full resync from server
          const msg =
            data.error === "no seeds"
              ? "ЁЯМ╛ No seeds left! Buy more in the shop тЖУ"
              : data.error === "plot occupied"
                ? "ЁЯЪл This plot is already in use"
                : `тЭМ ${data.error}`;
          showToast(msg);
          loadState();
        }
      })
      .catch(() => {
        if (plotPlantVersions.get(plotId) === ver) loadState();
      });
  }

  function water(plotId) {
    // Race guard: skip if already watering this plot
    if (wateringInFlight.has(plotId)) return;
    wateringInFlight.add(plotId);

    // Optimistic update (instant UI)
    state.plots[plotId] = { ...state.plots[plotId], watered: true };
    syncToStore();
    render();

    // v7.1: Farm Juice тАФ water shimmer + droplets
    const plotDiv = document.querySelector(
      `.farm-plot[data-index="${plotId}"]`,
    );
    if (plotDiv) {
      plotDiv.classList.add("water-shimmer");
      setTimeout(() => plotDiv.classList.remove("water-shimmer"), 1300);
      spawnWaterDroplets(plotDiv, 3);
    }

    showToast(`ЁЯТз Watered! Growth ~30% faster`);

    // Bug 4.1 fix: timeout fallback to release lock even if server is slow
    const fallbackTimer = setTimeout(
      () => wateringInFlight.delete(plotId),
      3000,
    );

    // Fire-and-forget with version guard
    const myVersion = ++waterVersion;
    apiBatched("/api/farm/water", { userId: HUB.userId, plotId })
      .then((data) => {
        clearTimeout(fallbackTimer);
        // Only delete the lock if we get a real response, NOT optimistic
        if (!data._optimistic) wateringInFlight.delete(plotId);
        if (waterVersion !== myVersion || data._optimistic) return;
        if (data.success) {
          if (data.plots) state.plots = data.plots;
          syncToStore();
        } else {
          loadState();
        }
      })
      .catch(() => {
        clearTimeout(fallbackTimer);
        wateringInFlight.delete(plotId);
        if (waterVersion === myVersion) loadState();
      });
  }

  function harvest(plotId) {
    // Optimistic: clear plot + show estimated reward instantly
    const plotSnapshot = { ...state.plots[plotId] };
    const cfg = crops[plotSnapshot.crop];
    const estimatedCoins = cfg?.sellPrice || 0;
    const estimatedXP = cfg?.xp || 0;

    state.plots[plotId] = { crop: null, plantedAt: null, watered: false };
    state.xp += estimatedXP;

    // Bug 2 fix: write harvested crop to resources.harvested in GameStore
    const res = GameStore.getState("resources") || {};
    const harvested = { ...(res.harvested || {}) };
    harvested[plotSnapshot.crop] = (harvested[plotSnapshot.crop] || 0) + 1;
    GameStore.setState("resources", { ...res, harvested: harvested });

    // v7.2: Check if harvest unlocked a new seed
    _checkNewUnlocks();

    syncToStore();

    // Phase 2 Item 5: Sparkle particle on harvest
    const plotDiv = document.querySelector(
      `.farm-plot[data-index="${plotId}"]`,
    );
    if (plotDiv) spawnFarmSparkle(plotDiv);

    // v7.1: Farm Juice тАФ harvest pop animation + coin fly to HUD
    if (plotDiv) {
      const emoji = plotDiv.querySelector(".crop-emoji");
      if (emoji) emoji.classList.add("harvest-pop");
      spawnCoinFly(plotDiv, 3);
    }

    render();
    renderShop();
    updateBuyBar();
    renderInventory();

    // Bug 3 fix: toast shows only XP, no gold (harvest doesn't award gold)
    showToast(`${cfg?.emoji || "ЁЯМ▒"} Harvested! +${estimatedXP}XP`);
    SoundEngine.harvest(); // v6.2.1: audio + haptic feedback

    // Fire-and-forget with version guard
    const myVersion = ++harvestVersion;
    apiBatched("/api/farm/harvest", { userId: HUB.userId, plotId })
      .then((data) => {
        if (harvestVersion !== myVersion || data._optimistic) return;
        if (data.success) {
          if (data.plots) state.plots = data.plots;
          state.xp = data.xp;
          state.level = data.level;
          if (data.resources) {
            HUD.syncFromServer(data.resources);
          }
          // Sync server harvested тЖТ resources.harvested
          if (data.harvested) syncHarvestedToStore(data.harvested);
          syncToStore();
          renderInventory();
          if (data.leveledUp) showToast(`ЁЯОЙ Level Up! Lv${data.level}`);
        } else {
          loadState();
        }
      })
      .catch(() => {
        if (harvestVersion === myVersion) loadState();
      });
  }

  /* тФАтФАтФА Uproot (ЁЯТг) тФАтФАтФА */
  async function uproot(plotId) {
    const plot = state?.plots?.[plotId];
    if (!plot || !plot.crop) return;
    const pct = getLocalGrowth(plot);
    if (pct >= 1) {
      showToast("ЁЯМ╛ Already ready тАФ harvest it!");
      return;
    }

    // Optimistic: clear the plot (NO seed refund)
    const oldPlot = { ...plot };
    state.plots[plotId] = { crop: null, plantedAt: null, watered: false };
    syncToStore();
    render();
    showToast("ЁЯТг Uprooted! No refund.");

    try {
      const data = await apiBatched("/api/farm/uproot", {
        userId: HUB.userId,
        plotId,
      });
      if (data._optimistic) return;
      if (data?.success) {
        if (data.plots) state.plots = data.plots;
        if (data.resources) HUD.syncFromServer(data.resources);
        syncToStore();
        render();
      } else {
        // Rollback
        state.plots[plotId] = oldPlot;
        syncToStore();
        render();
        showToast(data?.error || "Uproot failed", "error");
      }
    } catch {
      state.plots[plotId] = oldPlot;
      syncToStore();
      render();
      showToast("Network error", "error");
    }
  }

  /* тФАтФАтФА Sell Crop тФАтФАтФА */
  function sellCrop(cropId, sellPrice) {
    // GameStore always available in ESM
    const res = GameStore.getState("resources") || {};
    const harvested = { ...(res.harvested || {}) };
    if (!harvested[cropId] || harvested[cropId] <= 0) {
      showToast("тЭМ No crops to sell!");
      return;
    }
    // Optimistic: deduct crop, add gold
    harvested[cropId]--;
    if (harvested[cropId] <= 0) delete harvested[cropId];
    const newGold = (res.gold || 0) + sellPrice;
    GameStore.setState("resources", {
      ...res,
      gold: newGold,
      harvested: harvested,
    });
    renderInventory();
    render();
    showToast(`ЁЯТ░ Sold! +${sellPrice}ЁЯкЩ`);
    HUD.animateGoldChange(sellPrice);
    HUD.updateDisplay(GameStore.getState("resources"));

    apiBatched("/api/farm/sell-crop", { userId: HUB.userId, cropId })
      .then((data) => {
        if (data._optimistic) return;
        if (data?.success) {
          if (data.resources) HUD?.syncFromServer?.(data.resources);
          if (data.harvested) syncHarvestedToStore(data.harvested);
          renderInventory();
        }
      })
      .catch(() => {});
  }

  /* тФАтФАтФА Feed Pet (crop тЖТ energy) тФАтФАтФА */
  function feedPet(cropId) {
    // GameStore always available in ESM
    const res = GameStore.getState("resources") || {};
    const e = res.energy || {};
    const cfg = CROPS_CONFIG[cropId];
    const energyYield = cfg ? cfg.energyYield : 1;
    const fullnessYield = cfg ? cfg.fullnessYield : 5;

    // Bug 2.3: block feeding at max energy
    if (e.current >= e.max) {
      showToast("тЪб Energy full! Can't feed yet.");
      return;
    }
    // Satiety guard: block feeding if pet is full
    const pet = GameStore.getState("pet");
    if (pet && (pet.stats?.fullness ?? 0) >= 100) {
      showToast("ЁЯдв Pet is too full! Wait for digestion.");
      return;
    }
    const harvested = { ...(res.harvested || {}) };
    if (!harvested[cropId] || harvested[cropId] <= 0) {
      showToast("тЭМ No crops to feed!");
      return;
    }
    // Optimistic: deduct crop, add dynamic energy
    harvested[cropId]--;
    if (harvested[cropId] <= 0) delete harvested[cropId];
    const newEnergy = {
      ...e,
      current: Math.min(e.max, e.current + energyYield),
    };
    GameStore.setState("resources", {
      ...res,
      energy: newEnergy,
      harvested: harvested,
    });
    // Optimistic: update pet fullness
    if (pet) {
      GameStore.setState("pet", {
        ...pet,
        stats: {
          ...pet.stats,
          fullness: Math.min(100, (pet.stats?.fullness ?? 0) + fullnessYield),
        },
        lastDigestionTimestamp: Date.now(),
      });
    }
    renderInventory();
    showToast(`ЁЯНЦ Fed pet! +${energyYield}тЪб`);
    HUD.updateDisplay(GameStore.getState("resources"));

    apiBatched("/api/pet/feed", { userId: HUB.userId, cropId })
      .then((data) => {
        if (data._optimistic) return;
        if (data?.success) {
          if (data.resources) HUD?.syncFromServer?.(data.resources);
          if (data.harvested) syncHarvestedToStore(data.harvested);
          renderInventory();
        }
      })
      .catch(() => {});
  }

  /* тФАтФАтФА 7.4: Growth Time Estimate тФАтФАтФА */
  function formatTimeLeft(plot, pct) {
    if (pct >= 1) return "Ready!";
    const mult = plot.watered ? plot.wateringMultiplier || 0.7 : 1;
    const totalMs = (plot.growthTime || 15000) * mult;
    const remainMs = totalMs * (1 - pct);
    const secs = Math.ceil(remainMs / 1000);
    if (secs <= 0) return "Ready!";
    if (secs < 60) return `~${secs}s left`;
    const mins = Math.ceil(secs / 60);
    return `~${mins}m left`;
  }

  /* тФАтФАтФА Local Growth Computation (Issue 5, v4.9: clock-corrected) тФАтФАтФА */
  function getLocalGrowth(plot) {
    if (!plot.crop || !plot.plantedAt) return 0;
    const elapsed = getServerNow() - plot.plantedAt; // v4.9: use server-corrected time
    const mult = plot.watered ? plot.wateringMultiplier || 0.7 : 1;
    const gt = plot.growthTime || 15000;
    return Math.min(1, elapsed / (gt * mult));
  }

  /* тФАтФАтФА Local Growth Tick (replaces 2s polling) тФАтФАтФА */
  let growthTickId = null;
  let syncInterval = null;
  let _lastReadyCount = -1; // v4.15.2: Badge throttle

  function startLocalGrowthTick() {
    stopLocalGrowthTick();
    let prevHadGrowing = true; // assume growing on start
    growthTickId = setInterval(() => {
      if (!state?.plots) return;
      // v4.15.2: Skip render when farm screen is not active
      if (HUB.currentScreen !== 2) return;
      const hasGrowing = state.plots.some(
        (p) => p.crop && getLocalGrowth(p) < 1,
      );
      if (!hasGrowing && !prevHadGrowing) return; // nothing changed, skip
      // v4.11.1: Always render when transitioning from growingтЖТdone
      prevHadGrowing = hasGrowing;
      render();
      // v4.15.2: Throttle badge тАФ only update when ready count changes
      const readyCount = state.plots.filter(
        (p) => p.crop && getLocalGrowth(p) >= 1,
      ).length;
      if (readyCount !== _lastReadyCount) {
        _lastReadyCount = readyCount;
        updateFarmBadge();
      }
    }, 500);
    // Lazy server sync every 30s for drift correction
    syncInterval = setInterval(async () => {
      if (HUB.userId) await loadState();
    }, 30000);
  }

  function stopLocalGrowthTick() {
    if (growthTickId) {
      clearInterval(growthTickId);
      growthTickId = null;
    }
    if (syncInterval) {
      clearInterval(syncInterval);
      syncInterval = null;
    }
  }

  /* тФАтФАтФА Farm Badge Notification (Issue 7) тФАтФАтФА */
  function updateFarmBadge() {
    if (!state?.plots) return;
    const readyCount = state.plots.filter(
      (p) => p.crop && getLocalGrowth(p) >= 1,
    ).length;
    // Farm is screen index 2 (trivia=0, blox=1, farm=2, match3=3)
    const FARM_SCREEN = 2;
    const dot = document.querySelectorAll(".nav-dot")[FARM_SCREEN];
    const badge = document.getElementById("farm-ready-badge");
    if (dot) {
      dot.classList.toggle(
        "has-notification",
        readyCount > 0 && HUB.currentScreen !== FARM_SCREEN,
      );
    }
    if (badge) {
      if (readyCount > 0 && HUB.currentScreen !== FARM_SCREEN) {
        badge.textContent = `ЁЯМ╛ ├Ч${readyCount}`;
        badge.classList.add("show");
        // Direction: screens 0,1 are LEFT of farm тЖТ point right; screen 3 is RIGHT тЖТ point left
        badge.classList.toggle("point-right", HUB.currentScreen < FARM_SCREEN);
        badge.classList.toggle("point-left", HUB.currentScreen > FARM_SCREEN);
        badge.onclick = () => {
          goToScreen(FARM_SCREEN);
        };
      } else {
        badge.classList.remove("show", "point-left", "point-right");
      }
    }
  }

  /* тФАтФАтФА Buy Plot Card тФАтФАтФА */
  const BUY_PLOT_BASE = 200;
  const MAX_PLOTS = 12;

  function getBuyPlotCost() {
    const n = state?.plots?.length ?? 6;
    return BUY_PLOT_BASE * Math.pow(2, n - 6);
  }

  function appendBuyPlotCard(grid) {
    if (!state || state.plots.length >= MAX_PLOTS) return;
    const cost = getBuyPlotCost();
    const gold = HUD.getGold();
    const canAfford = gold >= cost;
    const card = document.createElement("div");
    card.className = `farm-plot buy-plot-card${canAfford ? "" : " disabled"}`;
    card.innerHTML = `
      <div style="font-size:1.6rem;opacity:0.5">тЮХ</div>
      <div class="plot-empty-label">Buy Plot</div>
      <div class="seed-price">ЁЯкЩ ${cost}</div>
    `;
    card.title = canAfford
      ? `Buy new plot for ${cost} gold`
      : `Need ${cost} gold`;
    if (canAfford) {
      card.onclick = () => buyPlot();
    }
    grid.appendChild(card);
  }

  function buyPlot() {
    if (!state || state.plots.length >= MAX_PLOTS) return;
    const cost = getBuyPlotCost();
    const gold = HUD.getGold();
    if (gold < cost) {
      showToast("тЭМ Not enough gold!");
      return;
    }

    // Optimistic: add empty plot instantly
    const prevPlots = [...state.plots];
    state.plots.push({ crop: null, plantedAt: null, watered: false });
    syncToStore();
    firstRenderDone = false; // Force full rebuild to add new plot
    render();
    showToast(`ЁЯМ▒ New plot unlocked! (${state.plots.length}/${MAX_PLOTS})`);
    HUD.animateGoldChange(-cost);

    // Fire-and-forget
    api("/api/farm/buy-plot", { userId: HUB.userId })
      .then((data) => {
        if (data?.success) {
          state.plots = data.plots;
          if (data.resources) {
            HUD.syncFromServer(data.resources);
          }
          syncToStore();
        } else {
          // Rollback
          state.plots = prevPlots;
          syncToStore();
          firstRenderDone = false;
          render();
          showToast(`тЭМ ${data?.error || "Failed to buy plot"}`);
        }
      })
      .catch(() => loadState());
  }

  /* тФАтФАтФА Phase 2 Item 5: Visual Effects (Bounce, Splash, Sparkle) тФАтФАтФА */
  function spawnDirtSplash(targetEl) {
    const rect = targetEl.getBoundingClientRect();
    const cx = rect.left + rect.width / 2;
    const cy = rect.top + rect.height - 20;

    for (let i = 0; i < 6; i++) {
      const particle = document.createElement("div");
      particle.className = "farm-dirt-particle";
      particle.style.left = `${cx}px`;
      particle.style.top = `${cy}px`;
      particle.style.setProperty("--vx", `${(Math.random() - 0.5) * 80}px`);
      particle.style.setProperty("--vy", `${-(Math.random() * 40 + 20)}px`);
      document.body.appendChild(particle);
      setTimeout(() => particle.remove(), 600);
    }
  }

  function spawnFarmSparkle(targetEl) {
    const rect = targetEl.getBoundingClientRect();
    const cx = rect.left + rect.width / 2;
    const cy = rect.top + rect.height / 2;

    for (let i = 0; i < 8; i++) {
      const particle = document.createElement("div");
      particle.className = "farm-sparkle-particle";
      particle.textContent = "тЬи";
      particle.style.left = `${cx}px`;
      particle.style.top = `${cy}px`;
      particle.style.setProperty("--vx", `${(Math.random() - 0.5) * 100}px`);
      particle.style.setProperty("--vy", `${(Math.random() - 0.5) * 100}px`);
      document.body.appendChild(particle);
      setTimeout(() => particle.remove(), 800);
    }
  }

  /* тФАтФАтФА Screen Enter/Exit тФАтФАтФА */
  function onEnter() {
    // Sync with server on enter, then rely on local timer
    loadState();
    startLocalGrowthTick();
  }

  return {
    init,
    onEnter,
    plant,
    water,
    harvest,
    harvestAll,
    buySeeds,
    buyPlot,
    selectSeed,
    updateFarmBadge,
    getLocalGrowth,
    sellCrop,
    feedPet,
    switchFarmTab,
  };
})();

export const FarmGame = FarmGameImpl;

/* тХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХР
 *  Game Hub тАФ HUD Module (v6.2.0)
 *  TopHUD for Energy & Gold display
 *  Registers 'resources' slice in GameStore
 *  v5: Native ES Module (was IIFE)
 * тХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХР */
import { GameStore } from "./store.js";
import { getCropsCache, loadCropsFromStorage } from "./crops.js";
import { HUB, api, goToScreen, showToast, safeShowModal } from "./shared.js";
import { CROPS, MERGE_CHAINS } from "/game-logic.js";

/* тФАтФАтФА Merge item display lookup (for quest requirement names) тФАтФАтФА */
const _MERGE_DISPLAY = {};
for (const chain of Object.values(MERGE_CHAINS)) {
  for (let i = 0; i < chain.items.length; i++) {
    _MERGE_DISPLAY[chain.items[i]] = {
      emoji: chain.emoji[i],
      name: chain.names[i],
    };
  }
}
function _formatReq(r) {
  if (r.type === "crop") {
    const c = CROPS[r.id];
    return `${c?.emoji || "ЁЯМ┐"} ${c?.name || r.id} ├Ч${r.qty}`;
  }
  const m = _MERGE_DISPLAY[r.id];
  return `${m?.emoji || "ЁЯзй"} ${m?.name || r.id} ├Ч${r.qty}`;
}
function _formatReward(rw) {
  const parts = [];
  if (rw.gold) parts.push(`+${rw.gold}ЁЯкЩ`);
  if (rw.affectionXp) parts.push(`+${rw.affectionXp}ЁЯТХ`);
  if (rw.gachaTokens) parts.push(`+${rw.gachaTokens}ЁЯО░`);
  if (rw.energyMaxBoost) parts.push(`+${rw.energyMaxBoost}тЪбmax`);
  return parts.join(" ") || "тАФ";
}

let regenTimerId = null;

// v4.15.2: Cached DOM refs (eliminates per-second getElementById calls)
let $energyText = null;
let $goldText = null;
let $energyEl = null;
let $regenFill = null;
let _lastRegenWidth = "";

/* тФАтФАтФА GameStore Slice Registration тФАтФАтФА */
function registerSlice() {
  GameStore.registerSlice("resources", {
    gold: 0,
    energy: { current: 0, max: 20, lastRegenTimestamp: Date.now() },
    gachaTokens: 0,
  });
}

/* тФАтФАтФА Fetch from server тФАтФАтФА */
async function fetchResources() {
  try {
    const data = await api("/api/resources/state");
    if (data && data.resources) {
      GameStore.setState("resources", data.resources);
      updateDisplay(data.resources);
      return data;
    }
  } catch (e) {
    console.warn("HUD: failed to fetch resources", e);
  }
  return null;
}

/* тФАтФАтФА Update Display тФАтФАтФА */
function updateDisplay(res) {
  if (!res) return;
  // React HUD listens to GameStore directly.
  // We mirror the critical values to a 'shared' slice for the React layer to read easily.
  const shared = GameStore.getState("shared") || {
    energy: 0,
    maxEnergy: 20,
    gold: 0,
    activeQuests: 0,
  };
  GameStore.setState("shared", {
    ...shared,
    energy: res.energy?.current || 0,
    maxEnergy: res.energy?.max || 20,
    gold: res?.gold || 0,
  });
}

function formatGold(amount) {
  if (amount >= 10000) return (amount / 1000).toFixed(1) + "k";
  return String(amount);
}

/* тФАтФАтФА Regen Timer тФАтФАтФА */
function updateTooltip(res) {
  const tooltip = document.getElementById("hud-energy-tooltip");
  if (!tooltip) return;

  if (res.energy.current >= res.energy.max) {
    tooltip.textContent = "Energy full!";
    return;
  }

  const elapsed = Date.now() - res.energy.lastRegenTimestamp;
  const interval = 150 * 1000; // 2.5 min тАФ matches game-logic.js ENERGY_REGEN_INTERVAL_MS
  const remaining = interval - (elapsed % interval);
  const mins = Math.floor(remaining / 60000);
  const secs = Math.floor((remaining % 60000) / 1000);
  tooltip.textContent = `Next +1тЪб in ${mins}:${String(secs).padStart(2, "0")}`;
}

function startRegenTimer() {
  stopRegenTimer();
  regenTimerId = setInterval(() => {
    const res = GameStore.getState("resources");
    if (res) {
      const e = { ...res.energy };
      const now = Date.now();
      const interval = 150 * 1000; // 2.5 min тАФ matches game-logic.js
      // v4.15.2: Early return when energy is full (skip all DOM ops)
      if (e.current >= e.max) {
        if (_lastRegenWidth !== "0%") {
          if (!$regenFill)
            $regenFill = document.getElementById("hud-energy-regen-fill");
          if ($regenFill) {
            $regenFill.style.width = "0%";
            // v4.15.3: Stop aurora animation when energy full
            $regenFill.classList.remove("aurora-active");
          }
          _lastRegenWidth = "0%";
        }
        return;
      }
      const delta = now - e.lastRegenTimestamp;
      const ticks = Math.floor(delta / interval);
      if (ticks > 0) {
        e.current = Math.min(e.max, e.current + ticks);
        if (e.current < e.max) {
          e.lastRegenTimestamp = now - (delta % interval);
        } else {
          e.lastRegenTimestamp = now;
        }
        GameStore.setState("resources", { ...res, energy: e });
      }
      // Update regen micro-progress bar
      const elapsed = now - e.lastRegenTimestamp;
      const pct = Math.min(100, (elapsed / interval) * 100);
      const newWidth = `${pct}%`;
      if (newWidth !== _lastRegenWidth) {
        if (!$regenFill)
          $regenFill = document.getElementById("hud-energy-regen-fill");
        if ($regenFill) {
          $regenFill.style.width = newWidth;
          // v4.15.3: Start aurora animation when regenerating
          if (!$regenFill.classList.contains("aurora-active")) {
            $regenFill.classList.add("aurora-active");
          }
        }
        _lastRegenWidth = newWidth;
      }
      updateDisplay({ ...res, energy: e });
    }
  }, 1000);
}

function stopRegenTimer() {
  if (regenTimerId) {
    clearInterval(regenTimerId);
    regenTimerId = null;
  }
}

/* тФАтФАтФА Gold Animation тФАтФАтФА */
function animateGoldChange(amount) {
  const goldEl = document.querySelector(".hud-gold");
  if (!goldEl) return;

  // Glassmorphism Spring Bump (Peak-End / Dopamine hit)
  goldEl.classList.remove("bump");
  void goldEl.offsetWidth; // Trigger reflow
  goldEl.classList.add("bump");

  const float = document.createElement("span");
  float.className = "hud-gold-change" + (amount < 0 ? " negative" : "");
  float.textContent = (amount > 0 ? "+" : "") + amount;
  goldEl.style.position = "relative";
  goldEl.appendChild(float);
  setTimeout(() => float.remove(), 1500);
}

/* тФАтФАтФА Energy Check (for gatekeeping) тФАтФАтФА */
function hasEnergy(amount) {
  const res = GameStore.getState("resources");
  return res && res.energy.current >= amount;
}

function getGold() {
  const res = GameStore.getState("resources");
  return res ? res.gold : 0;
}

/* тФАтФАтФА Update from server response тФАтФАтФА */
function syncFromServer(resources) {
  if (!resources) return;
  // Smart merge: trust server for energy.current and gold, but only
  // update lastRegenTimestamp if server's is newer тАФ prevents the
  // regen bar from jumping backward when local timer is ahead.
  const local = GameStore.getState("resources");
  const merged = { ...resources };
  if (local?.energy?.lastRegenTimestamp && resources.energy) {
    const serverTs = resources.energy.lastRegenTimestamp || 0;
    const localTs = local.energy.lastRegenTimestamp || 0;
    if (localTs > serverTs) {
      merged.energy = { ...resources.energy, lastRegenTimestamp: localTs };
    }
  }
  // Preserve local harvested (farm inventory state)
  if (local?.harvested && !merged.harvested) {
    merged.harvested = local.harvested;
  }
  GameStore.setState("resources", merged);
  updateDisplay(resources);
}

/* тФАтФАтФА Init тФАтФАтФА */
async function init() {
  registerSlice();
  const data = await fetchResources();
  if (data && data.resources) {
    updateDisplay(data.resources);
  }
  startRegenTimer();

  // Subscribe to store changes
  GameStore.subscribe("resources", (newState) => {
    updateDisplay(newState);
  });

  // Quest Log button
  const questLogBtn = document.getElementById("quest-log-btn");
  if (questLogBtn) questLogBtn.addEventListener("click", _openQuestLog);

  // Bind to the new Quest UI component
  document.addEventListener("quest-submit", async (e) => {
    await _submitQuestOrder(e.detail);
    _updateQuestBadge();
  });
  document.addEventListener("quest-generate", async () => {
    await _generateQuestOrders();
  });

  // Badge update: check periodically and on store changes
  GameStore.subscribe("pet", _updateQuestBadge);
  GameStore.subscribe("resources", _updateQuestBadge);
  setInterval(_updateQuestBadge, 5000);

  // v4.15.2: Pause regen timer when tab hidden (save CPU)
  document.addEventListener("visibilitychange", () => {
    if (document.hidden) {
      stopRegenTimer();
    } else {
      startRegenTimer(); // Resume + catch up on missed ticks
    }
  });
}

/* тФАтФАтФА Quick-Feed Energy Modal тФАтФАтФА */
let _energyModalPlayCb = null;
let _energyModalRequired = 0;

function showEnergyModal(requiredEnergy, onPlayCallback) {
  _energyModalRequired = requiredEnergy;
  _energyModalPlayCb = onPlayCallback;

  const modal = document.getElementById("energy-modal");
  const itemsEl = document.getElementById("energy-modal-items");
  const playEl = document.getElementById("energy-modal-play");
  const descEl = document.getElementById("energy-modal-desc");
  if (!modal || !itemsEl) return;

  // Get harvested crops from resources slice (unified source)
  const harvested = GameStore.getState("resources")?.harvested || {};

  const res = GameStore.getState("resources");
  const currentEnergy = res ? res.energy.current : 0;
  const needed = requiredEnergy - currentEnergy;

  descEl.textContent = `Need ${needed} more тЪб тАФ Feed your pet to restore energy!`;

  const cropsCache = getCropsCache() || loadCropsFromStorage();
  const entries = Object.entries(harvested).filter(([, qty]) => qty > 0);
  if (entries.length === 0) {
    itemsEl.innerHTML =
      '<p class="text-dim" style="font-size:0.82rem;margin:12px 0">No food available. Harvest some crops first!</p>';
  } else {
    itemsEl.innerHTML = entries
      .map(([cropId, qty]) => {
        const crop = cropsCache ? cropsCache[cropId] : null;
        const cfg = CROPS[cropId];
        const emoji = crop ? crop.emoji : cfg ? cfg.emoji : "ЁЯМ┐";
        const name = crop ? crop.name : cfg ? cfg.name : cropId;
        const ey = cfg ? cfg.energyYield : 1;
        return `
        <div class="energy-feed-item" data-crop="${cropId}">
          <span class="feed-icon">${emoji}</span>
          <div class="feed-info">
            <div class="feed-name">${name}</div>
            <div class="feed-qty">├Ч${qty} тАв +${ey}тЪб</div>
          </div>
          <button class="feed-btn" data-crop="${cropId}">Eat</button>
        </div>`;
      })
      .join("");
  }

  // Play button (hidden initially)
  playEl.style.display = "none";
  playEl.innerHTML = "";

  // Check if we already have enough
  _checkEnergyPlayReady();

  // Bind events
  itemsEl.onclick = (e) => {
    const btn = e.target.closest(".feed-btn");
    if (!btn || btn.disabled) return;
    const cropId = btn.dataset.crop;
    _feedFromModal(cropId, btn);
  };

  document.getElementById("energy-modal-farm").onclick = () => {
    hideEnergyModal();
    goToScreen(2); // Fix Bug 5: 2 is Farm, 1 was Blox
  };
  const closeBtn = document.getElementById("energy-modal-close");
  if (closeBtn) closeBtn.onclick = hideEnergyModal;

  safeShowModal(modal);
}

function hideEnergyModal() {
  const modal = document.getElementById("energy-modal");
  if (modal && modal.open) {
    modal.close();
  }
  _energyModalPlayCb = null;
}

async function _feedFromModal(cropId, btn) {
  btn.disabled = true;
  btn.textContent = "тАж";

  // Satiety guard: block feeding if pet is full
  const pet = GameStore.getState("pet");
  if (pet && (pet.stats?.fullness ?? 0) >= 100) {
    showToast("ЁЯдв Pet is too full! Wait for digestion.", "error");
    btn.disabled = false;
    btn.textContent = "Eat";
    return;
  }

  // Dynamic yield from crop config
  const cfg = CROPS[cropId];
  const energyYield = cfg ? cfg.energyYield : 1;
  const fullnessYield = cfg ? cfg.fullnessYield : 5;

  // Optimistic: add dynamic energy locally
  const res = GameStore.getState("resources");
  if (res) {
    const updated = {
      ...res,
      energy: {
        ...res.energy,
        current: Math.min(res.energy.max, res.energy.current + energyYield),
      },
    };
    syncFromServer(updated);
  }

  // Optimistic: update pet fullness
  if (pet) {
    GameStore.setState("pet", {
      ...pet,
      stats: {
        ...pet.stats,
        fullness: Math.min(100, (pet.stats?.fullness ?? 0) + fullnessYield),
      },
      lastDigestionTimestamp: Date.now(),
    });
  }

  // Optimistic: decrement harvested count (unified resources slice)
  const resAfter = GameStore.getState("resources");
  if (resAfter && resAfter.harvested && resAfter.harvested[cropId]) {
    const updated = { ...resAfter, harvested: { ...resAfter.harvested } };
    updated.harvested[cropId]--;
    if (updated.harvested[cropId] <= 0) delete updated.harvested[cropId];
    GameStore.setState("resources", updated);
  }

  try {
    // Server call
    const data = await api("/api/pet/feed", {
      cropId,
      userId: HUB.userId,
    });

    if (data && data.success) {
      if (data.resources) syncFromServer(data.resources);
    }
  } finally {
    // v6.2.0: Guaranteed refresh тАФ re-enables buttons even on network error
    _refreshModalItems();
    _checkEnergyPlayReady();
  }
}

function _refreshModalItems() {
  const itemsEl = document.getElementById("energy-modal-items");
  if (!itemsEl) return;

  const harvested = GameStore.getState("resources")?.harvested || {};

  // Update quantities and disable empty ones
  itemsEl.querySelectorAll(".energy-feed-item").forEach((item) => {
    const cropId = item.dataset.crop;
    const qty = harvested[cropId] || 0;
    const cfg = CROPS[cropId];
    const ey = cfg ? cfg.energyYield : 1;
    const qtyEl = item.querySelector(".feed-qty");
    const btn = item.querySelector(".feed-btn");
    if (qty <= 0) {
      item.style.opacity = "0.4";
      if (btn) {
        btn.disabled = true;
        btn.textContent = "Empty";
      }
    } else {
      item.style.opacity = "1";
      if (qtyEl) qtyEl.textContent = `├Ч${qty} тАв +${ey}тЪб`;
      if (btn) {
        btn.disabled = false;
        btn.textContent = "Eat";
      }
    }
  });
}

function _checkEnergyPlayReady() {
  const playEl = document.getElementById("energy-modal-play");
  if (!playEl) return;

  const res = GameStore.getState("resources");
  const current = res ? res.energy.current : 0;

  if (current >= _energyModalRequired && _energyModalPlayCb) {
    playEl.style.display = "block";
    playEl.innerHTML = '<button class="energy-play-btn">тЦ╢я╕П PLAY NOW</button>';
    playEl.querySelector(".energy-play-btn").onclick = () => {
      const cb = _energyModalPlayCb;
      hideEnergyModal();
      if (cb) cb();
    };
  }
}

/* тФАтФАтФА Quest Log тФАтФАтФА */
function _updateQuestBadge() {
  const pet = GameStore.getState("pet");
  const orders = pet?.activeOrders || [];
  const canSubmitAny = orders.some((o) => _canFulfillOrder(o));

  // Inform React layer
  const shared = GameStore.getState("shared") || { activeQuests: 0 };
  if (shared.activeQuests !== (canSubmitAny ? 1 : 0)) {
    GameStore.setState("shared", {
      ...shared,
      activeQuests: canSubmitAny ? 1 : 0,
    });
  }
}

function _canFulfillOrder(order) {
  const res = GameStore.getState("resources");
  const harvested = res?.harvested || {};
  const mergeState = GameStore.getState("merge");
  for (const req of order.requirements) {
    if (req.type === "crop") {
      if (!harvested[req.id] || harvested[req.id] < req.qty) return false;
    } else if (req.type === "merge") {
      const board = mergeState?.board;
      if (!board) return false;
      let found = 0;
      for (const row of board) {
        for (const cell of row) {
          if (cell && cell.id === req.id) found++;
        }
      }
      if (found < req.qty) return false;
    }
  }
  return true;
}

/** Get the player's current quantity for a quest requirement */
function _getPlayerQty(req) {
  if (req.type === "crop") {
    const res = GameStore.getState("resources");
    return (res?.harvested || {})[req.id] || 0;
  } else if (req.type === "merge") {
    const mergeState = GameStore.getState("merge");
    const board = mergeState?.board;
    if (!board) return 0;
    let found = 0;
    for (const row of board) {
      for (const cell of row) {
        if (cell && cell.id === req.id) found++;
      }
    }
    return found;
  }
  return 0;
}
function _openQuestLog() {
  document.dispatchEvent(new CustomEvent("toggle-quests"));

  // Auto-generate if empty and never done
  const _autoKey = "_questLogAutoGenDone";
  const pet = GameStore.getState("pet");
  const orders = pet?.activeOrders || [];
  if (orders.length === 0 && !sessionStorage.getItem(_autoKey)) {
    sessionStorage.setItem(_autoKey, "1");
    _generateQuestOrders();
  }
}

async function _generateQuestOrders() {
  const res = GameStore.getState("resources");
  try {
    const data = await api("/api/quests/generate", {
      userId: res?.userId || undefined,
    });
    if (!data?.success) {
      showToast(data?.error || "Could not generate orders", "error");
      return;
    }
    const pet = GameStore.getState("pet");
    if (pet && data.orders)
      GameStore.setState("pet", { ...pet, activeOrders: data.orders });
    showToast(`ЁЯУЬ ${data.newOrders?.length || 0} new orders!`, "success");
  } catch {
    showToast("Network error", "error");
  }
}

async function _submitQuestOrder(orderId) {
  const pet = GameStore.getState("pet");
  const res = GameStore.getState("resources");
  if (!pet || !res) return;
  const order = (pet.activeOrders || []).find((o) => o.id === orderId);
  if (!order) {
    showToast("Order not found", "error");
    return;
  }
  if (!_canFulfillOrder(order)) {
    showToast("Requirements not met", "error");
    return;
  }

  // Optimistic remove
  const oldOrders = [...(pet.activeOrders || [])];
  GameStore.setState("pet", {
    ...pet,
    activeOrders: pet.activeOrders.filter((o) => o.id !== orderId),
  });

  try {
    const data = await api("/api/quests/submit", {
      userId: res.userId || undefined,
      orderId,
    });
    if (!data?.success) {
      GameStore.setState("pet", { ...pet, activeOrders: oldOrders });
      showToast(data?.error || "Quest failed", "error");
      return;
    }
    if (data.pet) GameStore.setState("pet", data.pet);
    if (data.resources)
      GameStore.setState("resources", {
        ...data.resources,
        harvested: data.harvested || {},
      });
    if (data.merge) GameStore.setState("merge", data.merge);
    showToast(
      `тЬЕ Quest complete! ${_formatReward(data.reward || {})}`,
      "success",
    );
    if (data.affectionLeveledUp)
      showToast(
        `ЁЯТХ Affection Level Up! Lv${data.pet?.affectionLevel}`,
        "success",
      );
  } catch {
    GameStore.setState("pet", { ...pet, activeOrders: oldOrders });
    showToast("Network error", "error");
  }
}

