  // We re-import inside the IIFE via module-scoped references set below.
  // This avoids breaking the IIFE encapsulation while using the shared engine.

  let board = [];
  let score = 0;
  let movesLeft = 30;
  let combo = 0;
  let selected = null;
  let isAnimating = false;
  let highScore = 0;
  let gameActive = false;
