}

/* тХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХР
 *  Actions (Optimistic Update тЖТ Server Validation)
 * тХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХР */

/**
 * Tap generator: deducts 1 energy + 1 crop, spawns 2-5 items server-side.
 * Client sends request, server returns authoritative board.
 */
async function tapGenerator(chainId, cropId) {
  const res = GameStore.getState("resources");
  const mergeState = GameStore.getState("merge");
  if (!res || !mergeState) return { success: false };

  const chain = MERGE_CHAINS[chainId];
  if (!chain) return { success: false, reason: "UNKNOWN_CHAIN" };

  // Pre-flight checks (avoid unnecessary network call)
  if (res.energy.current < 1) {
    showToast("тЪб Not enough energy!", "error");
    return { success: false, reason: "NO_ENERGY" };
  }
  const harvested = res.harvested || {};
  if (!cropId || !harvested[cropId] || harvested[cropId] <= 0) {
    showToast("ЁЯМ▒ No crops to fuel generator!", "error");
    return { success: false, reason: "NO_CROP" };
  }
  const gs = mergeState.generatorState?.[chainId];
  if (gs && gs.cooldownEnd > Date.now()) {
    const mins = Math.ceil((gs.cooldownEnd - Date.now()) / 60000);
    showToast(`тП│ Generator cooling down (${mins}m left)`, "error");
    return { success: false, reason: "COOLDOWN" };
  }

  // Optimistic: deduct energy + crop immediately
  const oldRes = { ...res };
  const newHarvested = { ...harvested };
  newHarvested[cropId] = (newHarvested[cropId] || 0) - 1;
  if (newHarvested[cropId] <= 0) delete newHarvested[cropId];
  GameStore.setState("resources", {
    ...res,
    energy: { ...res.energy, current: res.energy.current - 1 },
    harvested: newHarvested,
  });
  HUD.updateDisplay(GameStore.getState("resources"));

  try {
    const data = await api("/api/merge/tap", {
      userId: HUB.userId,
      chainId,
      cropId,
    });
    if (!data?.success) {
      // Rollback
      GameStore.setState("resources", oldRes);
      HUD.updateDisplay(oldRes);
      showToast(data?.error || "Tap failed", "error");
      return { success: false };
    }
    // Sync authoritative state
    GameStore.setState("merge", data.merge);
    if (data.resources) {
      GameStore.setState("resources", {
        ...data.resources,
        harvested: data.harvested || {},
      });
      HUD.updateDisplay(data.resources);
    }
    _renderBoard();
    _renderGeneratorPanel();
    // Show spawned count
    showToast(
      `тЬи Spawned ${data.spawned?.length || 0} items! (-1тЪб)`,
      "success",
    );
    return { success: true, spawned: data.spawned };
  } catch (err) {
    // Rollback on network error
    GameStore.setState("resources", oldRes);
    HUD.updateDisplay(oldRes);
    showToast("Network error", "error");
    return { success: false };
  }
}

/**
 * Merge two items: client sends coords, server validates and returns new board.
 */
async function mergeItems(fromR, fromC, toR, toC) {
  const mergeState = GameStore.getState("merge");
  if (!mergeState) return { success: false };

  const board = mergeState.board;
  const src = board[fromR]?.[fromC];
  const dst = board[toR]?.[toC];
  if (!src || !dst) return { success: false, reason: "EMPTY_CELL" };
  if (src.chainId !== dst.chainId || src.level !== dst.level) {
    return { success: false, reason: "MISMATCH" };
  }
  const info = ITEM_LOOKUP[src.id];
  if (!info || !info.nextId) {
    showToast("тЬи Max level reached!", "info");
    return { success: false, reason: "MAX_LEVEL" };
  }

  // Optimistic: merge immediately in local state
  const oldBoard = structuredClone(board);
  const newBoard = structuredClone(board);
  const nextInfo = ITEM_LOOKUP[info.nextId];
  newBoard[toR][toC] = {
    id: info.nextId,
    chainId: src.chainId,
    level: nextInfo.level,
  };
  newBoard[fromR][fromC] = null;
  GameStore.setState("merge", { ...mergeState, board: newBoard });
  _renderBoard();

  try {
    const data = await api("/api/merge/merge", {
      userId: HUB.userId,
      fromR,
      fromC,
      toR,
      toC,
    });
    if (!data?.success) {
      // Rollback
      GameStore.setState("merge", { ...mergeState, board: oldBoard });
      _renderBoard();
      return { success: false };
    }
    // Sync authoritative board
    GameStore.setState("merge", data.merge);
    SoundEngine.merge(); // v6.2.1: audio + haptic feedback on merge success
    _renderBoard();
    return { success: true };
  } catch {
    GameStore.setState("merge", { ...mergeState, board: oldBoard });
    _renderBoard();
    return { success: false };
  }
}

/**
 * Roll gacha: costs 10 tokens, spawns random L0 item + unlocks chain.
 */
async function rollGacha() {
  const res = GameStore.getState("resources");
  if (!res || (res.gachaTokens || 0) < ECONOMY.GACHA_PULL_COST) {
    showToast(`ЁЯО░ Need ${ECONOMY.GACHA_PULL_COST} Gacha Tokens!`, "error");
    return { success: false };
  }

  // Optimistic: deduct tokens
  const oldTokens = res.gachaTokens;
  GameStore.setState("resources", {
    ...res,
    gachaTokens: res.gachaTokens - ECONOMY.GACHA_PULL_COST,
  });
  HUD.updateDisplay(GameStore.getState("resources"));

  try {
    const data = await api("/api/merge/gacha", { userId: HUB.userId });
    if (!data?.success) {
      GameStore.setState("resources", { ...res, gachaTokens: oldTokens });
      HUD.updateDisplay(GameStore.getState("resources"));
      showToast(data?.error || "Gacha failed", "error");
      return { success: false };
    }
    GameStore.setState("merge", data.merge);
    GameStore.setState("resources", data.resources);
    HUD.updateDisplay(data.resources);
    _renderBoard();
    _renderGeneratorPanel();
    showToast("ЁЯО░ Gacha roll! New item spawned!", "success");
    // v7.2: Gacha capsule drop + reveal juice
    _animateGachaDrop();
    return { success: true };
  } catch {
    GameStore.setState("resources", { ...res, gachaTokens: oldTokens });
    HUD.updateDisplay(GameStore.getState("resources"));
    return { success: false };
  }
}

/**
 * Daily free pull: 1 free item per UTC day.
 */
async function freePull() {
  try {
    const data = await api("/api/merge/free-pull", { userId: HUB.userId });
    if (!data?.success) {
      showToast(data?.error || "Free pull unavailable", "error");
      return { success: false };
    }
    GameStore.setState("merge", data.merge);
    _renderBoard();
    _renderGeneratorPanel();
    showToast("ЁЯОБ Daily free item!", "success");
    // v7.2: Gacha capsule drop juice
    _animateGachaDrop();
    return { success: true };
  } catch {
    showToast("Network error", "error");
    return { success: false };
  }
}

/**
 * Trash item at (r,c). Anti-softlock escape valve.
 */
async function trashMergeItem(r, c) {
  const mergeState = GameStore.getState("merge");
  if (!mergeState || !mergeState.board[r]?.[c]) return { success: false };

  // Snapshot for rollback
  const oldBoard = structuredClone(mergeState.board);
  const newBoard = structuredClone(mergeState.board);
  newBoard[r][c] = null;
  GameStore.setState("merge", { ...mergeState, board: newBoard });
  _renderBoard();

  try {
    const data = await api("/api/merge/trash", { userId: HUB.userId, r, c });
    if (!data?.success) {
      GameStore.setState("merge", { ...mergeState, board: oldBoard });
      _renderBoard();
    }
    return { success: true };
  } catch {
    GameStore.setState("merge", { ...mergeState, board: oldBoard });
    _renderBoard();
    return { success: false };
  }
}

/* тХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХР
 *  DOM Layer: 2D Cell Cache + Ghost-Pattern D&D
 * тХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХР */
let _cells = []; // 2D DOM cache: _cells[row][col]
let _boardEl = null;
let _dragState = null;
let _trashMode = false;
let _cachedMatchTargets = []; // OPTIMIZATION 1: Cache rects to avoid Layout Thrashing in RAF
let _selectedFuel = {}; // chainId тЖТ cropId (fuel slot memory)
let _idleHintTimer = null;
let _dragSafetyTimer = null; // v6.2.0: force-cleanup stuck drags
let _cooldownTimer = null; // v6.2.1: stored for cleanup in onLeave()
const IDLE_HINT_DELAY = 7000; // 7 seconds
const DRAG_SAFETY_TIMEOUT = 5000; // 5 seconds max drag duration

// [Phase 2] Global Event-Driven Garbage Collector
document.addEventListener("hub:route-leave", (e) => {
  // Clear RAM/DOM caches when leaving the screen
  _cachedMatchTargets = [];
  if (_dragState) {
    if (_dragState.ghost) _dragState.ghost.remove();
    if (_dragState.originCell) _dragState.originCell.classList.remove("merge-cell--dragging");
    _dragState = null;
  }
  if (_dragSafetyTimer) {
    clearTimeout(_dragSafetyTimer);
    _dragSafetyTimer = null;
  }
});

/* тФАтФАтФА Board Rendering тФАтФАтФА */
function createBoardDOM() {
  _boardEl = document.getElementById("merge-board");
  if (!_boardEl) return;

  // One-time build (never use innerHTML again after this)
  _boardEl.textContent = "";
  _cells = [];

  for (let r = 0; r < BOARD_ROWS; r++) {
    _cells[r] = [];
    for (let c = 0; c < BOARD_COLS; c++) {
      const cell = document.createElement("div");
      cell.className = "merge-cell";
      cell.dataset.row = r;
      cell.dataset.col = c;
      _boardEl.appendChild(cell);
      _cells[r][c] = cell;
    }
  }

  // Bind pointer events for ghost-pattern D&D
  _boardEl.addEventListener("pointerdown", _onPointerDown);
  document.addEventListener("pointermove", _onPointerMove);
  document.addEventListener("pointerup", _onPointerUp);
  document.addEventListener("pointercancel", _onPointerUp);

  _renderBoard();
}

function _renderBoard() {
  const mergeState = GameStore.getState("merge");
  if (!mergeState || !_boardEl) return;
  for (let r = 0; r < BOARD_ROWS; r++) {
    for (let c = 0; c < BOARD_COLS; c++) {
      _renderCell(r, c, mergeState.board[r][c]);
    }
  }
  // Empty-board onboarding hint
  const isEmpty = mergeState.board.every((row) =>
    row.every((cell) => cell === null),
  );
  let hint = _boardEl.querySelector(".merge-empty-hint");
  if (isEmpty && !hint) {
    hint = document.createElement("div");
    hint.className = "merge-empty-hint";
    hint.textContent =
      "ЁЯМ▒ Tap a generator below to start! Feed crops тЖТ get items тЖТ merge to level up";
    _boardEl.appendChild(hint);
  } else if (!isEmpty && hint) {
    hint.remove();
  }
  // Restart idle hint timer on any board render
  _resetIdleHintTimer();
}

/* v7.2: Gacha capsule drop + reveal animation on recently spawned cells */
function _animateGachaDrop() {
  if (!_boardEl) return;
  const cells = _boardEl.querySelectorAll(".merge-cell.merge-item");
  // Animate the last row of items (most likely newly spawned)
  const items = Array.from(cells).slice(-3);
  items.forEach((cell, i) => {
    cell.classList.add("gacha-dropping");
    cell.style.animationDelay = `${i * 80}ms`;
    cell.addEventListener(
      "animationend",
      function handler() {
        if (HUB.currentScreen !== 4) return; // OPTIMIZATION 8: Leak protection
        cell.classList.remove("gacha-dropping");
        cell.classList.add("gacha-reveal");
        cell.addEventListener(
          "animationend",
          () => {
            if (HUB.currentScreen === 4) cell.classList.remove("gacha-reveal");
          },
          { once: true },
        );
        cell.removeEventListener("animationend", handler);
      },
      { once: true },
    );
  });
}

function _renderCell(r, c, item) {
  const cell = _cells[r]?.[c];
  if (!cell) return;

  if (!item) {
    cell.textContent = "";
    cell.className = "merge-cell";
    cell.title = "";
    return;
  }

  const info = ITEM_LOOKUP[item.id];
  cell.textContent = info ? info.emoji : "тЭУ";
  cell.className = "merge-cell merge-item";
  cell.title = info ? `${info.name} (Lv${item.level + 1})` : item.id;

  // Level indicator via data attribute for CSS
  cell.dataset.level = item.level;
  cell.dataset.chain = item.chainId;
}

/* тФАтФАтФА Ghost-Pattern Drag & Drop тФАтФАтФА */

/** v6.2.0: Force-cleanup any stuck drag state + orphan ghosts */
function _forceCleanupDrag() {
  if (_dragSafetyTimer) {
    clearTimeout(_dragSafetyTimer);
    _dragSafetyTimer = null;
  }
  // Remove ALL orphan ghost divs from body
  document.querySelectorAll(".merge-drag-ghost").forEach((g) => g.remove());
  // Restore any dimmed cells
  if (_dragState?.originCell) {
    _dragState.originCell.classList.remove("merge-cell--dragging");
  }
  // Clear match highlights
  _cachedMatchTargets = [];
  if (_boardEl) {
    _boardEl
      .querySelectorAll(".merge-cell--match-highlight")
      .forEach((c) => c.classList.remove("merge-cell--match-highlight"));
  }
  HUB.swipeBlocked = false;
  _dragState = null;
}

function _onPointerDown(e) {
  // v6.2.0: Clean slate тАФ force-cleanup any stuck previous drag
  _forceCleanupDrag();

  if (_trashMode) {
    // Trash mode: click to remove
    const cell = e.target.closest(".merge-cell");
    if (!cell || !cell.classList.contains("merge-item")) return;
    const r = parseInt(cell.dataset.row, 10);
    const c = parseInt(cell.dataset.col, 10);
    trashMergeItem(r, c);
    e.preventDefault();
    return;
  }

  const cell = e.target.closest(".merge-cell");
  if (!cell || !cell.classList.contains("merge-item")) return;

  const r = parseInt(cell.dataset.row, 10);
  const c = parseInt(cell.dataset.col, 10);

  // Create ghost clone appended to <body> (NOT modifying the grid cell)
  const ghost = document.createElement("div");
  ghost.className = "merge-drag-ghost";
  ghost.textContent = cell.textContent;
  ghost.style.cssText = `
    position: fixed;
    left: 0; top: 0;
    --x: ${Math.round(e.clientX - 24)}px;
    --y: ${Math.round(e.clientY - 24)}px;
    --tilt: 0deg;
    transform: translate3d(var(--x), var(--y), 0) scale(1.15) rotate(var(--tilt));
    pointer-events: none;
    z-index: 9999;
    will-change: transform;
    font-size: 2rem;
    width: 48px; height: 48px;
    justify-content: center;
    border-radius: 12px;
    background: rgba(255,255,255,0.2);
    /* OPTIMIZATION 1: Replaced expensive backdrop-filter: blur with opacity */
    opacity: 0.9;
    box-shadow: 0 16px 32px rgba(0,0,0,0.5), inset 0 2px 4px rgba(255,255,255,0.4);
    transition: transform 0.08s cubic-bezier(0.2, 0.8, 0.2, 1);
  `;
  document.body.appendChild(ghost);

  // Dim source cell
  cell.classList.add("merge-cell--dragging");

  _dragState = {
    pointerId: e.pointerId,
    fromR: r,
    fromC: c,
    ghost,
    originCell: cell,
    lastX: e.clientX,
    lastY: e.clientY,
    cachedCSSX: e.clientX - 24,
    cachedCSSY: e.clientY - 24,
    cachedCSSTilt: 0,
  };

  // v6.2.0: Safety timeout тАФ force-cleanup if drag lives too long
  _dragSafetyTimer = setTimeout(() => {
    if (_dragState) {
      console.warn("[merge] Drag safety timeout тАФ force cleanup");
      _forceCleanupDrag();
    }
  }, DRAG_SAFETY_TIMEOUT);

  // Highlight matching items on board
  const mergeState = GameStore.getState("merge");
  const src = mergeState?.board[r]?.[c];
  _cachedMatchTargets = [];
  if (src) {
    for (let ri = 0; ri < BOARD_ROWS; ri++) {
      for (let ci = 0; ci < BOARD_COLS; ci++) {
        if (ri === r && ci === c) continue;
        const dst = mergeState.board[ri]?.[ci];
        if (dst && dst.id === src.id) {
          const targetCell = _cells[ri][ci];
          targetCell.classList.add("merge-cell--match-highlight");
          // OPTIMIZATION 1: Cache rect to avoid DOM queries during RAF drag
          const rect = targetCell.getBoundingClientRect();
          _cachedMatchTargets.push({
            el: targetCell,
            cx: rect.left + rect.width / 2,
            cy: rect.top + rect.height / 2,
          });
        }
      }
    }
  }

  // v6.2.0: Removed setPointerCapture тАФ document-level listeners handle everything
  HUB.swipeBlocked = true;
  e.preventDefault();
}

function _onPointerMove(e) {
  if (!_dragState || e.pointerId !== _dragState.pointerId) return;
  requestAnimationFrame(() => {
    if (!_dragState) return;

    // Phase 2 Item 4: Magnetic Snap + Elevation Drag (velocity tilt)
    let snapX = e.clientX - 24;
    let snapY = e.clientY - 24;
    const SNAP_RADIUS = 40;

    // OPTIMIZATION 1: Used cached targets array with zero DOM queries
    for (const t of _cachedMatchTargets) {
      const dist = Math.hypot(e.clientX - t.cx, e.clientY - t.cy);
      if (dist < SNAP_RADIUS) {
        snapX = t.cx - 24;
        snapY = t.cy - 24;
        t.el.classList.add("merge-cell--magnetic-lock");
      } else {
        t.el.classList.remove("merge-cell--magnetic-lock");
      }
    }

    const dx = e.clientX - (_dragState.lastX || e.clientX);
    _dragState.lastX = e.clientX;
    const tilt = Math.max(-12, Math.min(12, dx * 0.7));

    // OPTIMIZATION 8: CSS Custom Properties Binding + Sub-pixel Caching
    // Only update DOM if change is significant (> 0.5px) to save JS string allocs
    if (
      Math.abs(snapX - _dragState.cachedCSSX) > 0.5 ||
      Math.abs(snapY - _dragState.cachedCSSY) > 0.5 ||
      Math.abs(tilt - _dragState.cachedCSSTilt) > 1.0
    ) {
      _dragState.cachedCSSX = snapX;
      _dragState.cachedCSSY = snapY;
      _dragState.cachedCSSTilt = Math.round(tilt);
      
      const st = _dragState.ghost.style;
      st.setProperty("--x", `${Math.round(snapX)}px`);
      st.setProperty("--y", `${Math.round(snapY)}px`);
      st.setProperty("--tilt", `${Math.round(tilt)}deg`);
    }
  });
}

function _onPointerUp(e) {
  if (!_dragState || e.pointerId !== _dragState.pointerId) return;
  
  HUB.swipeBlocked = false;
  
  const ds = _dragState;
  _dragState = null;
  if (_dragSafetyTimer) {
    clearTimeout(_dragSafetyTimer);
    _dragSafetyTimer = null;
  }

  // Restore source cell
  ds.originCell.classList.remove("merge-cell--dragging");
  // Remove all match highlights and magnetic locks
  if (_boardEl) {
    _boardEl.querySelectorAll(".merge-cell--match-highlight").forEach((c) => {
      c.classList.remove("merge-cell--match-highlight");
      c.classList.remove("merge-cell--magnetic-lock");
    });
  }

  // Find drop target (hide ghost to avoid it being the target)
  ds.ghost.style.display = "none";
  const target = document
    .elementFromPoint(e.clientX, e.clientY)
    ?.closest(".merge-cell");
  ds.ghost.style.display = "";

  if (target && target !== ds.originCell) {
    const toR = parseInt(target.dataset.row, 10);
    const toC = parseInt(target.dataset.col, 10);

    // Try merge (async)
    mergeItems(ds.fromR, ds.fromC, toR, toC).then((result) => {
      if (result.success) {
        // Pop + collide animation on target
        target.classList.add("merge-pop");
        target.classList.add("merge-collide"); // v7.2: flash burst
        target.addEventListener(
          "animationend",
          () => {
            if (HUB.currentScreen === 4) {
              target.classList.remove("merge-pop");
              target.classList.remove("merge-collide");
            }
          },
          { once: true },
        );
      }
    });

    // Remove ghost immediately (merge result renders async)
    ds.ghost.remove();
  } else {
    // Spring return: animate ghost back to origin cell
    const cellRect = ds.originCell.getBoundingClientRect();
    ds.ghost.style.transition =
      "transform 0.3s cubic-bezier(0.34, 1.3, 0.64, 1)";
    ds.ghost.style.setProperty("--x", `${Math.round(cellRect.left)}px`);
    ds.ghost.style.setProperty("--y", `${Math.round(cellRect.top)}px`);
    ds.ghost.style.setProperty("--tilt", `0deg`);
    ds.ghost.addEventListener("transitionend", () => ds.ghost.remove(), {
      once: true,
    });
    // Fallback: remove after 500ms if transitionend doesn't fire
    setTimeout(() => {
      if (ds.ghost.parentNode) ds.ghost.remove();
    }, 500);
  }
}

/* тХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХР
 *  Generator Panel
 * тХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХР */
let _genPanel = null;

function _renderGeneratorPanel() {
  _genPanel = document.getElementById("merge-generators");
  if (!_genPanel) return;
  const mergeState = GameStore.getState("merge");
  const res = GameStore.getState("resources");
  if (!mergeState) return;

  _genPanel.textContent = "";

  // тФАтФАтФА Primary Section: Generators тФАтФАтФА
  const genSection = document.createElement("div");
  genSection.className = "merge-panel-section merge-gen-section";

  const genLabel = document.createElement("span");
  genLabel.className = "merge-section-label";
  genLabel.textContent = "тЪб Generators";
  genSection.appendChild(genLabel);

  const genRow = document.createElement("div");
  genRow.className = "merge-gen-row";

  for (const chainId of mergeState.generators) {
    const chain = MERGE_CHAINS[chainId];
    if (!chain) continue;
    const gs = mergeState.generatorState?.[chainId] || {
      tapsLeft: ECONOMY.GENERATOR_TAP_LIMIT,
      cooldownEnd: 0,
    };

    const btn = document.createElement("button");
    btn.className = "merge-gen-btn";
    const onCooldown = gs.cooldownEnd > Date.now();

    if (onCooldown) {
      const mins = Math.ceil((gs.cooldownEnd - Date.now()) / 60000);
      btn.textContent = `${chain.emoji[0]} тП│${mins}m`;
      btn.disabled = true;
      btn.classList.add("merge-gen-btn--cooldown");
    } else {
      btn.textContent = `${chain.emoji[0]} Tap (${gs.tapsLeft}/${ECONOMY.GENERATOR_TAP_LIMIT})`;
      btn.title = `Costs 1тЪб + 1 crop тЖТ ${chain.name} items`;
    }

    btn.addEventListener("click", () => _tapWithFuel(chainId));
    genRow.appendChild(btn);

    // Fuel slot badge (shows currently selected crop)
    const fuelCrop = _selectedFuel[chainId];
    if (fuelCrop && !onCooldown) {
      const cfg = CROPS[fuelCrop];
      const harvested = res?.harvested || {};
      const qty = harvested[fuelCrop] || 0;
      if (cfg && qty > 0) {
        const fuelBadge = document.createElement("button");
        fuelBadge.className = "merge-fuel-badge";
        fuelBadge.textContent = `${cfg.emoji} ├Ч${qty}`;
        fuelBadge.title = `Fuel: ${cfg.name} (click to change)`;
        fuelBadge.addEventListener("click", (e) => {
          e.stopPropagation();
          _showCropPicker(chainId);
        });
        genRow.appendChild(fuelBadge);
      }
    }
  }

  genSection.appendChild(genRow);
  _genPanel.appendChild(genSection);

  // тФАтФАтФА Secondary Section: Tools тФАтФАтФА
  const toolsRow = document.createElement("div");
  toolsRow.className = "merge-panel-section merge-tools-row";

  // Gacha button (with token count inline)
  const tokenCount = res?.gachaTokens || 0;
  const gachaBtn = document.createElement("button");
  gachaBtn.className = "merge-gen-btn merge-gacha-btn";
  gachaBtn.textContent = `ЁЯО░ Gacha (${tokenCount}/${ECONOMY.GACHA_PULL_COST})`;
  gachaBtn.title = `Spend ${ECONOMY.GACHA_PULL_COST} Gacha Tokens`;
  gachaBtn.disabled = tokenCount < ECONOMY.GACHA_PULL_COST;
  gachaBtn.addEventListener("click", rollGacha);
  toolsRow.appendChild(gachaBtn);

  // Free pull button
  const mergeData = GameStore.getState("merge");
  const lastPull = mergeData?.lastFreePull || 0;
  const todayStr = new Date().toISOString().slice(0, 10);
  const lastStr = new Date(lastPull).toISOString().slice(0, 10);
  const canFreePull = lastStr !== todayStr;

  const freeBtn = document.createElement("button");
  freeBtn.className = "merge-gen-btn merge-free-btn";
  freeBtn.textContent = canFreePull ? "ЁЯОБ Free" : "ЁЯОБ Used";
  freeBtn.disabled = !canFreePull;
  freeBtn.addEventListener("click", freePull);
  toolsRow.appendChild(freeBtn);

  // Trash toggle
  const trashBtn = document.createElement("button");
  trashBtn.className = `merge-gen-btn merge-trash-btn${_trashMode ? " active" : ""}`;
  trashBtn.textContent = "ЁЯЧСя╕П";
  trashBtn.title = "Click items on board to remove them";
  trashBtn.addEventListener("click", () => {
    _trashMode = !_trashMode;
    trashBtn.classList.toggle("active", _trashMode);
    if (_boardEl) _boardEl.classList.toggle("trash-mode", _trashMode);
  });
  toolsRow.appendChild(trashBtn);

  _genPanel.appendChild(toolsRow);
}

/* тФАтФАтФА Crop Picker Modal for Generator Tap тФАтФАтФА */
function _showCropPicker(chainId) {
  const res = GameStore.getState("resources");
  const harvested = res?.harvested || {};
  const cropIds = Object.keys(harvested).filter((id) => harvested[id] > 0);

  if (cropIds.length === 0) {
    showToast("ЁЯМ▒ No harvested crops! Grow some on the farm first.", "error");
    return;
  }

  // Native <dialog> тАФ consistent with project convention (v4.14+)
  const dialog = document.createElement("dialog");
  dialog.className = "modal merge-crop-picker";

  const title = document.createElement("h3");
  title.textContent = "Choose crop to fuel generator";
  dialog.appendChild(title);

  const subtitle = document.createElement("p");
  subtitle.className = "merge-crop-picker__hint";
  subtitle.textContent = "Better crops тЖТ more items spawned";
  dialog.appendChild(subtitle);

  const list = document.createElement("div");
  list.className = "merge-crop-picker__list";

  for (const cropId of cropIds) {
    const cfg = CROPS[cropId];
    if (!cfg) continue;
    const tier = CROP_TIERS[cropId] || "cheap";
    const btn = document.createElement("button");
    btn.className = `merge-crop-btn merge-crop-btn--${tier}`;
    btn.textContent = `${cfg.emoji} ${cfg.name} (├Ч${harvested[cropId]}) [${tier}]`;
    btn.addEventListener("click", () => {
      dialog.close();
      _selectedFuel[chainId] = cropId; // Remember fuel choice
      tapGenerator(chainId, cropId);
    });
    list.appendChild(btn);
  }

  dialog.appendChild(list);

  const cancelBtn = document.createElement("button");
  cancelBtn.className = "merge-crop-btn merge-crop-btn--cancel";
  cancelBtn.textContent = "тЬХ Cancel";
  cancelBtn.addEventListener("click", () => dialog.close());
  dialog.appendChild(cancelBtn);

  dialog.addEventListener("close", () => dialog.remove());
  // v6.2.0: Backdrop click-to-close (prevents invisible backdrop trapping all clicks)
  dialog.addEventListener("click", (e) => {
    if (e.target === dialog) dialog.close();
  });
  document.body.appendChild(dialog);
  safeShowModal(dialog);
}

/* тФАтФАтФА Fuel Slot: 1-click tap with remembered crop тФАтФАтФА */
function _tapWithFuel(chainId) {
  const fuelCrop = _selectedFuel[chainId];
  const res = GameStore.getState("resources");
  const harvested = res?.harvested || {};

  // If we have a remembered fuel and stock > 0, tap immediately
  if (fuelCrop && harvested[fuelCrop] && harvested[fuelCrop] > 0) {
    tapGenerator(chainId, fuelCrop);
    return;
  }
  // Otherwise show picker (first time or fuel exhausted)
  _showCropPicker(chainId);
}

/* тФАтФАтФА Idle Hint Timer (7s) тФАтФАтФА */
function _resetIdleHintTimer() {
  if (_idleHintTimer) clearTimeout(_idleHintTimer);
  // Remove previous hints
  if (_boardEl)
    _boardEl
      .querySelectorAll(".merge-cell--hint")
      .forEach((c) => c.classList.remove("merge-cell--hint"));
  _idleHintTimer = setTimeout(_showIdleHint, IDLE_HINT_DELAY);
}

function _showIdleHint() {
  const mergeState = GameStore.getState("merge");
  if (!mergeState || !_boardEl) return;
  // Find first mergeable pair
  for (let r = 0; r < BOARD_ROWS; r++) {
    for (let c = 0; c < BOARD_COLS; c++) {
      const item = mergeState.board[r]?.[c];
      if (!item) continue;
      const info = ITEM_LOOKUP[item.id];
      if (!info || !info.nextId) continue; // skip max level
      // Search for match
      for (let r2 = 0; r2 < BOARD_ROWS; r2++) {
        for (let c2 = 0; c2 < BOARD_COLS; c2++) {
          if (r2 === r && c2 === c) continue;
          const other = mergeState.board[r2]?.[c2];
          if (other && other.id === item.id) {
            // Found a pair тАФ wiggle both cells
            _cells[r][c].classList.add("merge-cell--hint");
            _cells[r2][c2].classList.add("merge-cell--hint");
            return; // Only hint one pair at a time
          }
        }
      }
    }
  }
}

/* тХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХР
 *  Init & Lifecycle
 * тХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХР */
function init() {
  registerSlice();
  createBoardDOM();
  _renderGeneratorPanel();

  // Subscribe to merge state changes
  // v6.2.1: split board vs panel subscription тАФ panel only re-renders when
  // generatorState/generators/lastFreePull changes (not on every drag/merge)
  let _prevGenState = null;
  GameStore.subscribe("merge", (prev, next) => {
    _renderBoard();
    const nextGenKey = JSON.stringify({
      g: next?.generators,
      gs: next?.generatorState,
      lp: next?.lastFreePull,
    });
    if (nextGenKey !== _prevGenState) {
      _prevGenState = nextGenKey;
      _renderGeneratorPanel();
    }
  });

  // Periodically refresh cooldown timers (stored for cleanup in onLeave)
  _cooldownTimer = setInterval(() => {
    if (document.hidden) return; // skip when tab is backgrounded
    const mergeState = GameStore.getState("merge");
    if (!mergeState) return;
    for (const chainId of mergeState.generators) {
      const gs = mergeState.generatorState?.[chainId];
      if (gs && gs.cooldownEnd > 0 && gs.cooldownEnd <= Date.now()) {
        // Cooldown expired тАФ refresh display
        gs.tapsLeft = ECONOMY.GENERATOR_TAP_LIMIT;
        gs.cooldownEnd = 0;
        _renderGeneratorPanel();
        break;
      }
    }
  }, 10000); // Check every 10s
}

async function onEnter() {
  // Fetch latest merge + resource state from server
  try {
    const data = await api("/api/merge/state", { userId: HUB.userId });
    if (data?.merge) GameStore.setState("merge", data.merge);
    if (data?.resources) {
      GameStore.setState("resources", data.resources);
      HUD.updateDisplay(data.resources);
    }
  } catch {
    // Use cached state
  }
  _renderBoard();
  _renderGeneratorPanel();
}

/** v6.2.1: Clean up timers when leaving the merge screen */
function onLeave() {
  if (_idleHintTimer) {
    clearTimeout(_idleHintTimer);
    _idleHintTimer = null;
  }
  // Clear any lingering match-highlight from an interrupted drag
  _forceCleanupDrag();
}

/* тХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХР
 *  Public API
 * тХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХР */
export const MergeGame = {
  init,
  onEnter,
  onLeave,
  tapGenerator,
  mergeItems,
  rollGacha,
  freePull,
  trashMergeItem,
};

/* тХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХР
 *  Game Hub тАФ Pet Module (v6.2.0)
 *  Living Pet Entity with state machine & interactions
 *  v1.8: Weighted behavior, zone roaming, FLIP dock
 *  v5: Native ES Module (was IIFE)
 * тХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХРтХР */
import { GameStore } from "./store.js";
import { api, showToast } from "./shared.js";
import {
  calculateSatietyDelta,
  CROPS,
  MERGE_CHAINS,
  getRoomBonuses,
  PET_ASSETS,
  PET_EXPRESSIONS,
} from "/game-logic.js";

/* тФАтФАтФА Merge item display lookup (for quest requirement names) тФАтФАтФА */
const _MERGE_DISPLAY = {};
for (const chain of Object.values(MERGE_CHAINS)) {
  for (let i = 0; i < chain.items.length; i++) {
    _MERGE_DISPLAY[chain.items[i]] = {
      emoji: chain.emoji[i],
      name: chain.names[i],
    };
  }
}

/** Format a quest requirement for display */
function _formatReq(r) {
  if (r.type === "crop") {
    const c = CROPS[r.id];
    return `${c?.emoji || "ЁЯМ┐"} ${c?.name || r.id} ├Ч${r.qty}`;
  }
  const m = _MERGE_DISPLAY[r.id];
  return `${m?.emoji || "ЁЯзй"} ${m?.name || r.id} ├Ч${r.qty}`;
}

/** Format reward object for display (used in both preview and toast) */
function _formatReward(rw) {
  const parts = [];
  if (rw.gold) parts.push(`+${rw.gold}ЁЯкЩ`);
  if (rw.affectionXp) parts.push(`+${rw.affectionXp}ЁЯТХ`);
  if (rw.gachaTokens) parts.push(`+${rw.gachaTokens}ЁЯО░`);
  if (rw.energyMaxBoost) parts.push(`+${rw.energyMaxBoost}тЪбmax`);
  return parts.join(" ") || "тАФ";
}

// тФАтФАтФА FarmGame.water() injected from main.js to avoid circular import тФАтФАтФА
let _waterFn = null;
export function setWaterFn(fn) {
  _waterFn = fn;
}

const PetCompanionImpl = (function () {
  const STATES = {
    IDLE: "idle",
    ROAM: "roam",
    SLEEP: "sleep",
    HAPPY: "happy",
    DIZZY: "dizzy",
  };
  const SKINS = {
    basic_dog: "ЁЯРХ",
    basic_cat: "ЁЯР▒",
    basic_bunny: "ЁЯР░",
  };

  let currentState = STATES.IDLE;
  let petData = null;
  let clickCount = 0;
  let clickResetTimer = null;
  let stateTimer = null;
  let inactivityTimer = null;
  let sleepTimer = null;
  let roamTimeoutId = null; // Track active roam timeout for cancellation
  let previousState = STATES.IDLE; // For anti-repeat logic
  let panelOpen = false;
  let dockMode = "ground"; // "ground" | "match3" | "trivia"

  // v4.15.2: Heart particle object pool (eliminates DOM churn)
  const HEART_POOL_SIZE = 5;
  let heartPool = [];
  let heartPoolIdx = 0;

  /* тФАтФАтФА GameStore Slice тФАтФАтФА */
  function registerSlice() {
    GameStore.registerSlice("pet", {
      name: "Buddy",
      level: 1,
      xp: 0,
      xpToNextLevel: 100,
      skinId: "basic_dog",
      stats: { happiness: 100, fullness: 0 },
      lastDigestionTimestamp: Date.now(),
      activeOrders: [],
      affectionXp: 0,
      affectionLevel: 1,
      abilities: { autoHarvest: false, autoWater: false },
    });
    GameStore.registerSlice("room", { decorations: [], wallpaper: "default" });
  }

  /* тФАтФАтФА Init тФАтФАтФА */
  async function init() {
    registerSlice();
    const container = document.getElementById("pet-container");
    const sprite = document.getElementById("pet-sprite");
    if (!container || !sprite) return;

    // Fetch pet data (included in resources/state)
    try {
      const data = await api("/api/resources/state");
      if (data && data.pet) {
        petData = data.pet;
        GameStore.setState("pet", data.pet);
        if (data.room) GameStore.setState("room", data.room);
        _renderPetStack();

        // Peak-End / IKEA Effect: Name pet at start if it's the default name
        if (data.pet.name === "Buddy" && data.pet.level === 1) {
          setTimeout(() => promptForPetName(data.pet.name), 2000);

          if (!localStorage.getItem("_pet_first_tap_nudge")) {
            setTimeout(() => {
              showBubble("Tap me to see my stats! тЬи");
              localStorage.setItem("_pet_first_tap_nudge", "1");
            }, 5000);
          }
        }
      }
    } catch (e) {
      console.warn("Pet: failed to fetch state", e);
    }

    // Click handler
    let hasDragged = false;
    container.addEventListener("click", (e) => {
      if (hasDragged) {
        e.stopPropagation();
        e.preventDefault();
        return;
      }
      onPetClick();
    });

    // Drag & Drop Physics
    let isDragging = false;
    let dragStartPointerX = 0;
    let dragStartPointerY = 0;
    let dragAbsX = 0; // Absolute X tracked internally (avoids re-reading computed transform)
    let dragAbsY = 0;

    container.addEventListener("pointerdown", (e) => {
      isDragging = true;
      hasDragged = false;
      dragStartPointerX = e.clientX;
      dragStartPointerY = e.clientY;

      // Capture the pet's current absolute X position ONCE from the computed style
      const matrix = new DOMMatrix(getComputedStyle(container).transform);
      dragAbsX = matrix.m41;
      dragAbsY = 0;

      if (roamTimeoutId) {
        clearTimeout(roamTimeoutId);
        roamTimeoutId = null;
      }
      container.classList.remove("pet-roaming");
      container.classList.remove("pet-transitioning");

      STATE_CLASSES.forEach((cls) => container.classList.remove(cls));
      container.classList.add("state-drag");
      currentState = "drag";

      container.style.willChange = "transform";
      container.setPointerCapture(e.pointerId);
    });

    container.addEventListener("pointermove", (e) => {
      if (!isDragging) return;

      const dx = e.clientX - dragStartPointerX;
      const dy = e.clientY - dragStartPointerY;

      if (Math.abs(dx) > 5 || Math.abs(dy) > 5) hasDragged = true;

      if (!hasDragged) return;

      // Accumulate delta onto the captured absolute position
      dragAbsX += e.clientX - dragStartPointerX;
      dragAbsY += e.clientY - dragStartPointerY;
      // Clamp Y so pet doesn't go below ground
      if (dragAbsY > 0) dragAbsY = 0;

      // Update pointer origin for next frame's delta
      dragStartPointerX = e.clientX;
      dragStartPointerY = e.clientY;

      // Position using the absolute X; no translateX(-50%) to avoid offset drift
      container.style.transform = `translate3d(${dragAbsX}px, ${dragAbsY}px, 0)`;
    });

    container.addEventListener("pointerup", (e) => {
      if (!isDragging) return;
      isDragging = false;
      container.releasePointerCapture(e.pointerId);

      if (hasDragged) {
        container.classList.remove("state-drag");
        container.classList.add("state-drop");

        // Drop to ground (Y=0) at the current X
        container.style.transition =
          "transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1)";
        container.style.transform = `translate3d(${dragAbsX}px, 0, 0)`;

        setTimeout(() => {
          container.classList.remove("state-drop");
          container.style.transition = "";
          setState(STATES.IDLE);
          scheduleNextState();
        }, 400);
      } else {
        container.classList.remove("state-drag");
        setState(STATES.IDLE);
        scheduleNextState();
      }
    });

    // Start state machine
    setState(STATES.IDLE);
    scheduleNextState();
    resetInactivityTimer();

    // Subscribe to store
    GameStore.subscribe("pet", (newState) => {
      petData = newState;
      _updateMoodIndicator();
      if (panelOpen) renderInfoPanel();
    });

    // Start auto-water butler ability
    startAutoWater();

    // Start satiety digestion ticker (minutely online decay)
    _startDigestionTicker();

    // Recalculate satiety on tab focus (visibility change)
    document.addEventListener("visibilitychange", () => {
      if (!document.hidden) _recalcSatiety();
    });

    // GPU cleanup: clear will-change after roam transition ends
    container.addEventListener("transitionend", () => {
      if (!container.classList.contains("pet-roaming")) {
        container.style.willChange = "auto";
      }
    });

    // Click-outside to close info panel handled by React now

    // v4.15.2: Pre-create heart particle pool
    const heartsEl = document.getElementById("pet-hearts");
    if (heartsEl && heartPool.length === 0) {
      for (let i = 0; i < HEART_POOL_SIZE; i++) {
        const el = document.createElement("span");
        el.className = "pet-heart";
        el.style.display = "none";
        heartsEl.appendChild(el);
        heartPool.push(el);
      }
    }
  }

  /* тФАтФАтФА State Machine (class-based тАФ synchronous, zero-flicker) тФАтФАтФА */
  const STATE_CLASSES = [
    "state-idle",
    "state-roam",
    "state-sleep",
    "state-happy",
    "state-dizzy",
    "state-drag",
    "state-drop",
  ];

  function setState(newState) {
    currentState = newState;
    const container = document.getElementById("pet-container");
    if (!container) return;

    // Cancel any active roam (prevents orphaned timeout removing classes later)
    if (roamTimeoutId) {
      clearTimeout(roamTimeoutId);
      roamTimeoutId = null;
    }
    container.classList.remove("pet-roaming");

    // Synchronous class swap тАФ no rAF, no animation reset, zero flicker
    STATE_CLASSES.forEach((cls) => container.classList.remove(cls));
    container.classList.add(`state-${newState}`);

    // Sleep overlay
    const heartsEl = document.getElementById("pet-hearts");
    if (heartsEl) {
      heartsEl.querySelectorAll(".pet-zzz").forEach((el) => el.remove());
      if (newState === STATES.SLEEP) {
        const zzz = document.createElement("span");
        zzz.className = "pet-zzz";
        zzz.textContent = "ЁЯТд";
        heartsEl.appendChild(zzz);
      }
    }
  }

  function scheduleNextState() {
    if (stateTimer) clearTimeout(stateTimer);
    const delay = 3000 + Math.random() * 4000; // 3-7s (lively tempo)
    stateTimer = setTimeout(() => {
      if (currentState === STATES.HAPPY || currentState === STATES.DIZZY) {
        // Don't interrupt reaction states
        scheduleNextState();
        return;
      }
      if (currentState === STATES.SLEEP) {
        // Stay asleep until interaction or auto-wake
        return;
      }

      // Weighted behavior: 80% ROAM, 15% IDLE, 5% SLEEP
      // Anti-repeat: skip SLEEP if previous was SLEEP
      let roll = Math.random();
      const canRoam =
        dockMode === "ground" || dockMode === "match3" || dockMode === "trivia";

      // Anti-repeat adjustments
      if (previousState === STATES.SLEEP) {
        // After waking, never immediately sleep again
        roll = Math.random() * 0.95; // Clamp out SLEEP range (0.95-1.0)
      }

      previousState = currentState;

      if (roll < 0.8 && canRoam) {
        // 80%: ROAM (most movement тАФ lively pet)
        setState(STATES.ROAM);
        roamToRandomPosition();
      } else if (roll < 0.95) {
        // 15%: IDLE (brief pause)
        setState(STATES.IDLE);
      } else {
        // 5%: SLEEP (short nap, 12s max)
        enterSleep();
      }
      scheduleNextState();
    }, delay);
  }

  /** Enter sleep state with 30s auto-wake timer */
  function enterSleep() {
    setState(STATES.SLEEP);
    if (sleepTimer) clearTimeout(sleepTimer);
    sleepTimer = setTimeout(() => {
      // Auto-wake after 12 seconds (short nap)
      if (currentState === STATES.SLEEP) {
        setState(STATES.IDLE);
        scheduleNextState();
      }
    }, 12000);
  }

  function roamToRandomPosition() {
    const container = document.getElementById("pet-container");
    const overlay = document.getElementById("pet-overlay");
    if (!container || !overlay) return;

    let minX, maxX;
    const w = window.innerWidth;

    if (dockMode === "ground") {
      // Farm: full-screen roaming with padding
      minX = 40;
      maxX = w - 40;
    } else if (dockMode === "match3" || dockMode === "trivia") {
      // Mirror CSS stats-bar width: min(520px, calc(100vw - 80px)), centered
      const panelW = Math.min(520, w - 80);
      minX = (w - panelW) / 2 + 20; // 20px inner padding
      maxX = (w + panelW) / 2 - 20;
    } else {
      setState(STATES.IDLE);
      return;
    }

    // Ensure valid range
    if (maxX <= minX) {
      setState(STATES.IDLE);
      return;
    }

    const newX = minX + Math.random() * (maxX - minX);

    // Determine direction from current position
    const computedStyle = getComputedStyle(container);
    const matrix = new DOMMatrix(computedStyle.transform);
    const currentX = matrix.m41;

    // Set direction for walk animation (invert: emoji ЁЯРХ faces LEFT, so scaleX(-1) = going right)
    const goingRight = newX > currentX;
    container.style.setProperty("--pet-dir", goingRight ? "-1" : "1");

    // v7.2: Dust puff on direction change
    container.classList.remove("pet-dust-puff");
    void container.offsetWidth;
    container.classList.add("pet-dust-puff");
    container.addEventListener(
      "animationend",
      () => container.classList.remove("pet-dust-puff"),
      { once: true },
    );

    // Unified flow: set state class synchronously, then position via single rAF
    STATE_CLASSES.forEach((cls) => container.classList.remove(cls));
    container.classList.add("state-roam");
    currentState = STATES.ROAM;
    container.classList.add("pet-roaming");

    container.style.transform = `translate3d(${newX}px, 0, 0) translateX(-50%)`;

    // Return to idle after reaching destination
    roamTimeoutId = setTimeout(() => {
      roamTimeoutId = null;
      container.classList.remove("pet-roaming");
      if (currentState === STATES.ROAM) {
        setState(STATES.IDLE);
      }
    }, 3000);
  }

  /* тФАтФАтФА Render Engine тФАтФАтФА */
  function _renderPetStack() {
    const spriteContainer = document.getElementById("pet-sprite");
    if (!spriteContainer || !petData) return;

    const baseSkinId = petData.skinId || "basic_dog";
    const assetDef = PET_ASSETS[baseSkinId];

    // Fallback if missing schema
    if (!assetDef) {
      spriteContainer.innerHTML = SKINS[baseSkinId] || SKINS.basic_dog;
      return;
    }

    // Determine current Expression from Happiness
    const happiness = petData.stats?.happiness ?? 100;
    let exprId;
    if (happiness >= 90) exprId = "ecstatic";
    else if (happiness >= 70) exprId = "happy";
    else if (happiness >= 50) exprId = "content";
    else if (happiness >= 30) exprId = "neutral";
    else if (happiness >= 15) exprId = "sad";
    else exprId = "miserable";

    const expressionDef = PET_EXPRESSIONS[exprId];

    // Build Layer Stack
    let html = `<div class="pet-render-stack" style="width: ${assetDef.width}px; height: ${assetDef.height}px;">`;

    // 1. Base Body Layer
    if (assetDef.type === "svg") {
      html += `<img class="pet-layer pet-body pet-type-svg" src="${assetDef.src}" alt="${baseSkinId}" />`;
    } else if (assetDef.type === "raster_spritesheet") {
      html += `<div class="pet-layer pet-body pet-type-raster" style="background-image: url('${assetDef.src}'); width: ${assetDef.frameWidth}px; animation-timing-function: steps(${assetDef.frames});"></div>`;
    }

    // 2. Facial Expression Layer (Anchored to 'face')
    if (expressionDef && assetDef.anchors?.face) {
      const faceAnchor = assetDef.anchors.face;
      html += `<img class="pet-layer pet-expression" src="${expressionDef.src}" style="top: ${faceAnchor.top}; left: ${faceAnchor.left}; transform: translate(-50%, -50%);" />`;
    }

    // 3. Cosmetics / Wardrobe (TODO: Inject equipped items here based on anchors)
    // if (petData.wardrobe?.hat) { ... }

    html += `</div>`;

    // Check if the HTML actually changed to prevent DOM thrashing re-paints
    if (spriteContainer.innerHTML !== html) {
      spriteContainer.innerHTML = html;
      spriteContainer.classList.add("pet-has-stack");
    }
  }

  /* тФАтФАтФА Pet Action/Mood Bubble тФАтФАтФА */
  function showBubble(text) {
    const container = document.getElementById("pet-container");
    if (!container) return;
    // Remove any existing bubble
    const old = container.querySelector(".pet-bubble");
    if (old) old.remove();
    const bubble = document.createElement("div");
    bubble.className = "pet-bubble";
    bubble.textContent = text;
    container.appendChild(bubble);
    setTimeout(() => bubble.remove(), 2500);
  }

  function _updateMoodIndicator() {
    const indicator = document.getElementById("pet-mood-indicator");
    if (!indicator || !petData) return;

    // Determine Mood
    const happiness = petData.stats?.happiness ?? 100;
    const fullness = petData.stats?.fullness ?? 0;
    let emoji;

    if (fullness >= 90) {
      emoji = "ЁЯдв"; // Too full
    } else if (fullness >= 70) {
      emoji = "ЁЯШЛ"; // Full
    } else if (happiness >= 90) {
      emoji = "ЁЯдй"; // Ecstatic
    } else if (happiness >= 50) {
      indicator.style.display = "none"; // Neutral/Content -> hidden to reduce noise
      return;
    } else if (happiness >= 20) {
      emoji = "ЁЯШФ"; // Sad
    } else {
      emoji = "ЁЯШн"; // Miserable
    }

    indicator.style.display = "flex";
    indicator.textContent = emoji;
  }

  /* тФАтФАтФА Auto-Water (Butler ability, level тЙе 3) тФАтФАтФА */
  let autoWaterTimer = null;
  function startAutoWater() {
    if (autoWaterTimer) clearInterval(autoWaterTimer);
    autoWaterTimer = setInterval(() => {
      if (!petData || petData.level < 3) return;
      if (currentState === STATES.SLEEP) return;
      // Check for crops needing water via GameStore
      const farmState = GameStore.getState("farm");
      if (!farmState || !farmState.plots) return;

      // Water up to 2 plots per tick
      let watered = 0;
      for (let i = 0; i < farmState.plots.length && watered < 2; i++) {
        const p = farmState.plots[i];
        if (p.crop && !p.watered && _waterFn) {
          _waterFn(i);
          watered++;
        }
      }
      if (watered > 0) {
        showBubble(`ЁЯТз Watered ${watered}!`);
        // No setState(HAPPY) тАФ bubble is sufficient, avoids animation pop
      }
    }, 10000); // Every 10s, up to 2 plants
  }

  /* тФАтФАтФА Inactivity тЖТ Sleep тФАтФАтФА */
  function resetInactivityTimer() {
    if (inactivityTimer) clearTimeout(inactivityTimer);
    inactivityTimer = setTimeout(() => {
      if (currentState !== STATES.HAPPY && currentState !== STATES.DIZZY) {
        setState(STATES.SLEEP);
      }
    }, 30000); // 30s
  }

  /* тФАтФАтФА Click Interaction тФАтФАтФА */
  function onPetClick() {
    resetInactivityTimer();

    // Wake up from sleep (cancel auto-wake timer)
    if (currentState === STATES.SLEEP) {
      if (sleepTimer) {
        clearTimeout(sleepTimer);
        sleepTimer = null;
      }
      setState(STATES.IDLE);
      scheduleNextState();
      spawnHeart();
      return;
    }

    clickCount++;
    if (clickResetTimer) clearTimeout(clickResetTimer);
    clickResetTimer = setTimeout(() => {
      clickCount = 0;
    }, 2000);

    if (clickCount >= 3) {
      // Easter egg: dizzy on rapid multi-tap
      setState(STATES.DIZZY);
      clickCount = 0;
      setTimeout(() => {
        setState(STATES.IDLE);
        scheduleNextState();
      }, 2000);
    } else {
      setState(STATES.HAPPY);
      spawnHeart();
      // v7.2: Tap bounce juice
      const c = document.getElementById("pet-container");
      if (c) {
        c.classList.add("state-tapped");
        c.addEventListener(
          "animationend",
          () => c.classList.remove("state-tapped"),
          { once: true },
        );
      }

      // v7.2: Single-tap to open info panel instead of triple tap
      // Let animation play out before opening to give satisfying feedback
      setTimeout(() => {
        setState(STATES.IDLE);
        if (!panelOpen) toggleInfoPanel();
      }, 300);
    }
  }

  function spawnHeart() {
    if (heartPool.length === 0) return;
    const el = heartPool[heartPoolIdx % HEART_POOL_SIZE];
    heartPoolIdx++;

    const emojis = ["тЭдя╕П", "ЁЯТХ", "тЬи", "тнР"];
    el.textContent = emojis[Math.floor(Math.random() * emojis.length)];
    el.style.setProperty("--hx", Math.random() * 30 - 15 + "px");

    // Re-trigger animation by removing/re-adding class
    el.classList.remove("pet-heart");
    el.style.display = "";
    void el.offsetWidth;
    el.classList.add("pet-heart");
    setTimeout(() => {
      el.style.display = "none";
    }, 1200);
  }

  /* тФАтФАтФА Info Panel тФАтФАтФА */
  let _lastToggle = 0;
  function toggleInfoPanel() {
    // Cooldown: ignore rapid toggles (within 600ms)
    const now = Date.now();
    if (now - _lastToggle < 600) return;
    _lastToggle = now;

    panelOpen = !panelOpen;
    // Dispatch to React layer instead of showing vanilla DOM modal
    document.dispatchEvent(
      new CustomEvent("toggle-pet-info", { detail: { open: panelOpen } }),
    );
  }

  // Sync panelOpen when React closes the panel (click-outside or тЬХ button)
  document.addEventListener("pet-info-closed", () => {
    panelOpen = false;
  });

  function renderInfoPanel() {
    const panel = document.getElementById("pet-info-panel");
    if (!panel || !petData) return;

    const xpPct = ((petData.xp / petData.xpToNextLevel) * 100).toFixed(1);
    const fullness = petData.stats?.fullness ?? 0;
    const orders = petData.activeOrders || [];

    panel.innerHTML = `
      <button class="pet-info-close" id="pet-info-close">тЬХ</button>
      <div class="pet-info-header">
        <span class="pet-info-name">${SKINS[petData.skinId] || "ЁЯРХ"} ${petData.name} <button class="btn btn-sm" id="btn-rename-pet" style="padding: 2px 6px; font-size: 0.7rem; margin-left: 6px; background: rgba(255,255,255,0.1);">тЬПя╕П</button></span>
        <span class="pet-info-level">Lv ${petData.level}</span>
      </div>
      <div class="pet-tab-content" id="pet-tab-stats">
        <div class="pet-info-xp-bar">
          <div class="pet-info-xp-fill" style="width: ${xpPct}%"></div>
        </div>
        <div class="pet-info-xp-text">${petData.xp} / ${petData.xpToNextLevel} XP</div>
        <div class="pet-satiety-bar">
          <div class="pet-satiety-fill" style="width: ${fullness}%"></div>
        </div>
        <div class="pet-satiety-text">${fullness >= 100 ? "ЁЯдв Full!" : `ЁЯНЦ Fullness: ${fullness}/100`}</div>
        <div class="pet-info-abilities">
          <span class="pet-ability ${petData.abilities.autoHarvest ? "unlocked" : ""}"
                title="Automatically harvests fully grown crops while you're offline (costs 1тЪб each)">
            ${petData.abilities.autoHarvest ? "тЬЕ" : "ЁЯФТ"} Auto-Harvest (Lv 3)
          </span>
          <span class="pet-ability ${petData.abilities.autoWater ? "unlocked" : ""}"
                title="Automatically waters unwatered crops while you're offline (free)">
