/* тФАтФАтФА Keyboard Navigation тФАтФАтФА */
export function bindKeyboardNav() {
  document.addEventListener("keydown", (e) => {
    // Don't hijack keyboard when user is typing in an input/textarea
    if (
      e.target.tagName === "INPUT" ||
      e.target.tagName === "TEXTAREA" ||
      e.target.isContentEditable
    )
      return;
    if (e.key === "ArrowLeft") {
      e.preventDefault();
      navigate(-1);
    } else if (e.key === "ArrowRight") {
      e.preventDefault();
      navigate(1);
    }
  });
}

/* тФАтФАтФА Touch Swipe Gestures тФАтФАтФА */
export function bindTouchSwipe() {
  const viewport = document.querySelector(".viewport");
  if (!viewport) return;

  let startX = 0;
  let startY = 0;
  let swiping = false;

  viewport.addEventListener(
    "touchstart",
    (e) => {
      startX = e.touches[0].clientX;
      startY = e.touches[0].clientY;
      swiping = true;
    },
    { passive: true },
  );

  viewport.addEventListener(
    "touchend",
    (e) => {
      if (!swiping) return;
      if (HUB.swipeBlocked) {
        swiping = false;
        return;
      }
      swiping = false;
      const endX = e.changedTouches[0].clientX;
      const endY = e.changedTouches[0].clientY;
      const dx = endX - startX;
      const dy = endY - startY;
      const THRESHOLD = 50;

      // Only trigger if horizontal swipe is dominant
      if (Math.abs(dx) > THRESHOLD && Math.abs(dx) > Math.abs(dy) * 1.2) {
        if (dx < 0)
          navigate(1); // swipe left тЖТ next
        else navigate(-1); // swipe right тЖТ prev
      }
    },
    { passive: true },
  );
}

